function seek(v,t){v.currentTime=clamp(t,0,Number.isFinite(v.duration)?Math.max(0,v.duration-.001):999999)}
function stepFrames(v,n,fps){v.pause();seek(v,v.currentTime+n/fps)}
function bindPan(vid,v){let down=false,start=null;base={x:v.panX||0,y:v.panY||0};const stage=$('.video-stage');stage.onpointerdown=e=>{if(state.drawMode||v.zoom<=1||e.target.closest('button'))return;down=true;start={x:e.clientX,y:e.clientY};stage.setPointerCapture?.(e.pointerId)};stage.onpointermove=e=>{if(!down)return;v.panX=base.x+e.clientX-start.x;v.panY=base.y+e.clientY-start.y;vid.style.transform=`translate(${v.panX}px,${v.panY}px) scale(${v.zoom}) rotate(${v.rotation||0}deg)${v.mirror?' scaleX(-1)':''}`};stage.onpointerup=()=>{down=false;base={x:v.panX||0,y:v.panY||0};persist('videos')}}
function openNote(vid,id=null){state.editNoteId=id;render();setTimeout(()=>{const d=$('#note-dialog');if(state.settings.notePause)vid?.pause();d?.showModal()},0)}
function bindNoteDialog(vid){const d=$('#note-dialog');if(!d)return;const existing=state.notes.find(x=>x.id===state.editNoteId);$('#note-save').onclick=()=>{const kind=$('#note-kind').value,title=$('#note-title').value.trim()||'無題メモ',body=$('#note-body').value.trim(),range=$('#note-range').checked,ab=activeV().ab||{};if(existing){existing.kind=kind;existing.title=title;existing.body=body;if(range&&ab.a!=null&&ab.b!=null){existing.type='range';existing.start=ab.a;existing.end=ab.b;existing.time=ab.a}else{existing.type='point';existing.time=vid.currentTime;delete existing.start;delete existing.end}}else{const n={id:uid('n'),videoId:activeV().id,kind,title,body,type:'point',time:vid.currentTime,tagIds:[]};if(range&&ab.a!=null&&ab.b!=null){n.type='range';n.start=ab.a;n.end=ab.b;n.time=ab.a;state.scenes.push({id:uid('s'),videoId:n.videoId,start:n.start,end:n.end,title,tagIds:[],favorite:false});persist('scenes')}state.notes.push(n)}persist('notes');state.editNoteId=null;d.close();toast('メモを保存しました');render()};$('#note-delete')?.addEventListener('click',()=>{state.notes=state.notes.filter(x=>x.id!==existing.id);persist('notes');state.editNoteId=null;d.close();render()});$$('[data-edit-note]').forEach(b=>b.onclick=e=>{e.stopPropagation();openNote(vid,b.dataset.editNote)})}
function saveScene(vid){const ab=activeV().ab||{};let start=ab.a,end=ab.b;if(start==null||end==null){start=Math.max(0,vid.currentTime-2);end=Math.min(vid.duration||vid.currentTime+2,vid.currentTime+2)}const s={id:uid('s'),videoId:activeV().id,start,end,title:`保存シーン ${fmt(start,true)}`,tagIds:[],favorite:false};state.scenes.push(s);persist('scenes');state.activeTab='scene';toast('シーンを保存しました');render()}
