function drawingLifetime(t,videoId){if(state.drawLifetime==='3s')return{start:t,end:t+3};if(state.drawLifetime==='scene'){const s=state.scenes.find(s=>s.videoId===videoId&&t>=s.start&&t<=s.end);if(s)return{start:s.start,end:s.end}}const fps=video(videoId)?.fps||30;return{start:t-1/fps/2,end:t+1/fps/2}}
function canvasCtx(c){const ctx=c.getContext('2d');const sx=c.width/(c.clientWidth||c.width),sy=c.height/(c.clientHeight||c.height);return{ctx,w:c.width,h:c.height,sx,sy}}
function redrawDrawings(t){const c=$('#draw-canvas');if(!c)return;const {ctx,w,h}=canvasCtx(c);ctx.clearRect(0,0,w,h);state.drawings.filter(d=>d.videoId===activeV().id&&t>=d.start&&t<=d.end).forEach(d=>drawShape(ctx,d,w,h))}
function previewDrawing(c,t,d){redrawDrawings(t);const {ctx,w,h}=canvasCtx(c);drawShape(ctx,d,w,h)}
function drawShape(ctx,d,w,h){const pts=d.points.map(p=>({x:p.x*w,y:p.y*h}));ctx.save();ctx.strokeStyle=d.color||'#ff3b30';ctx.fillStyle=d.color||'#ff3b30';ctx.lineWidth=(d.width||3)*devicePixelRatio;ctx.lineCap='round';ctx.lineJoin='round';if(!pts.length){ctx.restore();return}if(d.type==='free'){ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);pts.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.stroke()}else if(d.type==='line'||d.type==='arrow'){const a=pts[0],b=pts.at(-1);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(d.type==='arrow'){const ang=Math.atan2(b.y-a.y,b.x-a.x),len=14*devicePixelRatio;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-len*Math.cos(ang-.5),b.y-len*Math.sin(ang-.5));ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-len*Math.cos(ang+.5),b.y-len*Math.sin(ang+.5));ctx.stroke()}}else if(d.type==='rect'){const a=pts[0],b=pts.at(-1);ctx.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y)}else if(d.type==='circle'){const a=pts[0],b=pts.at(-1),rx=Math.abs(b.x-a.x)/2,ry=Math.abs(b.y-a.y)/2;ctx.beginPath();ctx.ellipse((a.x+b.x)/2,(a.y+b.y)/2,rx,ry,0,0,Math.PI*2);ctx.stroke()}else if(d.type==='angle'&&pts.length>=3){ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);ctx.lineTo(pts[1].x,pts[1].y);ctx.lineTo(pts[2].x,pts[2].y);ctx.stroke();ctx.font=`${14*devicePixelRatio}px sans-serif`;ctx.fillText(`${Math.round(d.angle||calcAngle(d.points[0],d.points[1],d.points[2]))}°`,pts[1].x+8,pts[1].y-8)}ctx.restore()}
function calcAngle(a,b,c){const v1={x:a.x-b.x,y:a.y-b.y},v2={x:c.x-b.x,y:c.y-b.y};const dot=v1.x*v2.x+v1.y*v2.y,mag=Math.hypot(v1.x,v1.y)*Math.hypot(v2.x,v2.y);return Math.acos(clamp(dot/(mag||1),-1,1))*180/Math.PI}
function eraseAt(p,videoId,t){const cand=state.drawings.filter(d=>d.videoId===videoId&&t>=d.start&&t<=d.end);let best=null,dist=Infinity;cand.forEach(d=>d.points.forEach(q=>{const x=Math.hypot(q.x-p.x,q.y-p.y);if(x<dist){dist=x;best=d}}));if(best&&dist<.08){state.drawings=state.drawings.filter(d=>d.id!==best.id);state.drawingUndo.push([best]);persist('drawings');redrawDrawings(t)}}
function undoDrawing(videoId){const arr=state.drawings.filter(d=>d.videoId===videoId);const last=arr.at(-1);if(!last)return;state.drawings=state.drawings.filter(d=>d.id!==last.id);state.drawingRedo.push(last);persist('drawings');redrawDrawings(state.playerTime||0)}
function redoDrawing(videoId){const d=state.drawingRedo.pop();if(!d||d.videoId!==videoId)return;state.drawings.push(d);persist('drawings');redrawDrawings(state.playerTime||0)}
function updateTimeMeasure(){const l=$('#time-measure-label');if(!l)return;l.textContent=state.measureA!=null&&state.measureB!=null?`時間 ${Math.abs(state.measureB-state.measureA).toFixed(3)}秒`:`時間計測 ${state.measureA!=null?'A='+fmt(state.measureA,true):'--'}`}
async function exportCurrentFrame(vid,v){const c=document.createElement('canvas');c.width=vid.videoWidth||1280;c.height=vid.videoHeight||720;const ctx=c.getContext('2d');try{ctx.save();if(v.mirror){ctx.translate(c.width,0);ctx.scale(-1,1)}ctx.drawImage(vid,0,0,c.width,c.height);ctx.restore();const items=state.drawings.filter(d=>d.videoId===v.id&&vid.currentTime>=d.start&&vid.currentTime<=d.end);items.forEach(d=>drawShape(ctx,d,c.width,c.height));c.toBlob(b=>b&&dl(b,`${v.title}_${fmt(vid.currentTime,true).replace(':','-')}.png`),'image/png')}catch(e){toast('静止画を書き出せませんでした')}}
async function exportSceneClip(s){const v=video(s.videoId);await hydrateVideo(v);if(!v.src)return toast('元動画を再関連付けしてください');const temp=document.createElement('video');temp.src=v.src;temp.muted=false;temp.playsInline=true;temp.style.display='none';document.body.appendChild(temp);await new Promise(res=>temp.onloadedmetadata=res);temp.currentTime=s.start;await new Promise(res=>temp.onseeked=res);if(!temp.captureStream){temp.remove();return toast('このブラウザはクリップ書き出しに未対応です')}const stream=temp.captureStream();const rec=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm'}),chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=()=>{dl(new Blob(chunks,{type:'video/webm'}),`${s.title}.webm`);temp.remove();toast('クリップを書き出しました')};rec.start();temp.play();const tick=()=>{if(temp.currentTime>=s.end||temp.ended){temp.pause();rec.stop()}else requestAnimationFrame(tick)};tick();toast('シーンを実時間で書き出しています')}
function bindPlaylistRuntime(vid){if(!state.activePlaylist)return;const pl=state.playlists.find(x=>x.id===state.activePlaylist);if(!pl)return;const item=pl.items[state.playlistIndex],s=scene(item?.sceneId);if(!s){state.activePlaylist=null;return}if(activeV().id!==s.videoId){state.activeVideo=s.videoId;render();return}const start=()=>{if(Math.abs(vid.currentTime-s.start)>.2)vid.currentTime=s.start};if(vid.readyState>=1)start();else vid.addEventListener('loadedmetadata',start,{once:true});const old=vid.ontimeupdate;vid.ontimeupdate=()=>{old?.();if(vid.currentTime>=s.end-.03){state.playlistLoopDone++;if(state.playlistLoopDone<(item.loopCount||1)){vid.currentTime=s.start;if(!vid.paused)vid.play()}else if(pl.autoplayNext!==false&&state.playlistIndex<pl.items.length-1){state.playlistLoopDone=0;state.playlistIndex++;const next=scene(pl.items[state.playlistIndex].sceneId);state.activeVideo=next.videoId;render();setTimeout(()=>$('#main-video')?.play(),100)}else{vid.pause();state.activePlaylist=null;state.playlistIndex=0;state.playlistLoopDone=0;toast('プレイリスト再生完了')}}}}

