function bindPlaylistDialog(){const d=$('#playlist-dialog');if(!d)return;const pl=state.playlists.find(x=>x.id===state.editPlaylistId);$('#pl-save')?.addEventListener('click',()=>{if(pl){pl.title=$('#pl-title').value.trim()||pl.title;pl.description=$('#pl-desc').value.trim();pl.autoplayNext=$('#pl-autoplay').checked;$$('[data-pl-loop]').forEach(x=>pl.items[+x.dataset.plLoop].loopCount=clamp(+x.value||1,1,20))}else state.playlists.push({id:uid('pl'),title:$('#pl-title').value.trim()||'無題プレイリスト',description:$('#pl-desc').value.trim(),items:[],autoplayNext:$('#pl-autoplay').checked});persist('playlists');d.close();render()});$$('[data-pl-up]').forEach(b=>b.onclick=()=>movePlaylistItem(pl,+b.dataset.plUp,-1));$$('[data-pl-down]').forEach(b=>b.onclick=()=>movePlaylistItem(pl,+b.dataset.plDown,1));$$('[data-pl-remove]').forEach(b=>b.onclick=()=>{pl.items.splice(+b.dataset.plRemove,1);persist('playlists');render();setTimeout(()=>{$('#playlist-dialog').showModal();bindPlaylistDialog()},0)});$('#pl-delete')?.addEventListener('click',()=>{state.playlists=state.playlists.filter(x=>x.id!==pl.id);persist('playlists');d.close();render()})}
function movePlaylistItem(pl,i,d){const j=clamp(i+d,0,pl.items.length-1);[pl.items[i],pl.items[j]]=[pl.items[j],pl.items[i]];persist('playlists');render();setTimeout(()=>{$('#playlist-dialog').showModal();bindPlaylistDialog()},0)}

function bindResearch(){$('#research-add').onclick=()=>$('#research-add-dialog').showModal();$('#theme-edit').onclick=()=>{state.editThemeId=state.activeTheme;render();setTimeout(()=>$('#theme-dialog').showModal(),0)};$('#theme-switch').onclick=()=>{const cur=state.themes.findIndex(t=>t.id===state.activeTheme);state.activeTheme=state.themes[(cur+1)%state.themes.length]?.id||state.activeTheme;render()};$('#lane-manage').onclick=()=>$('#lane-dialog').showModal();bindThemeDialog();bindLaneDialog();bindResearchAdd();bindResearchDrag();$$('[data-remove-card]').forEach(b=>b.onclick=()=>{state.researchCards=state.researchCards.filter(c=>c.id!==b.dataset.removeCard);persist('researchCards');render()})}
function bindThemeDialog(){const d=$('#theme-dialog');if(!d)return;const t=theme(state.editThemeId);$('#theme-save')?.addEventListener('click',()=>{if(t){t.title=$('#th-title').value.trim()||t.title;t.question=$('#th-question').value.trim();t.hypothesis=$('#th-hypothesis').value.trim();t.conclusion=$('#th-conclusion').value.trim();t.nextAction=$('#th-next').value.trim();t.status=$('#th-status').value;t.revisitDate=$('#th-date').value}else{const nt={id:uid('rt'),title:$('#th-title').value.trim()||'無題研究',question:$('#th-question').value.trim(),hypothesis:$('#th-hypothesis').value.trim(),conclusion:$('#th-conclusion').value.trim(),nextAction:$('#th-next').value.trim(),status:$('#th-status').value,revisitDate:$('#th-date').value,lanes:['未整理','成功例','改善例','参考','反例']};state.themes.push(nt);state.activeTheme=nt.id}persist('themes');state.editThemeId=null;d.close();render()});$('#theme-delete')?.addEventListener('click',()=>{state.themes=state.themes.filter(x=>x.id!==t.id);state.researchCards=state.researchCards.filter(c=>c.themeId!==t.id);state.activeTheme=state.themes[0]?.id;persistMany('themes','researchCards');d.close();render()})}
function bindLaneDialog(){const d=$('#lane-dialog'),t=theme(state.activeTheme);if(!d||!t)return;$('#lane-add').onclick=()=>{t.lanes.push('新しいレーン');persist('themes');render();setTimeout(()=>$('#lane-dialog').showModal(),0)};$$('[data-lane-up]').forEach(b=>b.onclick=()=>moveLane(t,+b.dataset.laneUp,-1));$$('[data-lane-down]').forEach(b=>b.onclick=()=>moveLane(t,+b.dataset.laneDown,1));$$('[data-lane-delete]').forEach(b=>b.onclick=()=>{const i=+b.dataset.laneDelete,l=t.lanes[i];state.researchCards.filter(c=>c.themeId===t.id&&c.lane===l).forEach(c=>c.lane='未整理');t.lanes.splice(i,1);persistMany('themes','researchCards');render();setTimeout(()=>$('#lane-dialog').showModal(),0)});$('#lane-save').onclick=()=>{$$('[data-lane-name]').forEach(x=>{const i=+x.dataset.laneName,old=t.lanes[i],nw=x.value.trim()||old;if(nw!==old){state.researchCards.filter(c=>c.themeId===t.id&&c.lane===old).forEach(c=>c.lane=nw);t.lanes[i]=nw}});persistMany('themes','researchCards');d.close();render()}}
