function bindResearchAdd(){const d=$('#research-add-dialog');if(!d)return;$('#ra-type').onchange=e=>{$('#ra-ref-wrap').style.display=e.target.value==='scene'?'block':'none'};$('#ra-save').onclick=()=>{const type=$('#ra-type').value,lane=$('#ra-lane').value;if(type==='scene')addResearchCard(state.activeTheme,'scene',$('#ra-scene').value,lane);else if(type==='comparison'){const c=state.comparisons.at(-1);if(!c)return toast('保存した比較がありません');addResearchCard(state.activeTheme,'comparison',c.id,lane)}else addResearchCard(state.activeTheme,'text','',lane,$('#ra-text').value.trim()||'テキスト');d.close();render()}}
function bindResearchDrag(){let dragged=null;$$('[data-research-card]').forEach(el=>el.ondragstart=()=>dragged=el.dataset.researchCard);$$('[data-drop-lane]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('drag-over')};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=e=>{e.preventDefault();el.classList.remove('drag-over');const c=state.researchCards.find(x=>x.id===dragged);if(c){c.lane=el.dataset.dropLane;c.order=state.researchCards.filter(x=>x.themeId===c.themeId&&x.lane===c.lane).length+1;persist('researchCards');render()}}})}

function bindCompare(){let a=video(state.compareLeftId),b=video(state.compareRightId);Promise.all([hydrateVideo(a),hydrateVideo(b)]).then(()=>{});let d=state.compareDraft||{leftAnchor:a.last||0,rightAnchor:b.last||0,offsetFrames:0,opacity:.5,memo:'',speed:1,title:`${a.title} vs ${b.title}`};state.compareDraft=d;const va=$('#cmp-a'),vb=$('#cmp-b');if(!va||!vb)return;const fps=a.fps||30;const offsetSec=()=>d.offsetFrames/fps;const sync=()=>{const desired=d.rightAnchor+(va.currentTime-d.leftAnchor)+offsetSec();if(Math.abs(vb.currentTime-desired)>.045)vb.currentTime=clamp(desired,0,Math.max(0,(vb.duration||desired)-.01))};const setSpeed=x=>{va.playbackRate=vb.playbackRate=x;d.speed=x};va.onplay=()=>vb.play().catch(()=>{});va.onpause=()=>vb.pause();va.ontimeupdate=sync;$('#cmp-play').onclick=()=>va.paused?va.play():va.pause();$('#cmp-back').onclick=()=>{va.pause();stepFrames(va,-1,fps);sync()};$('#cmp-next').onclick=()=>{va.pause();stepFrames(va,1,fps);sync()};$('#cmp-back5').onclick=()=>{va.pause();stepFrames(va,-5,fps);sync()};$('#cmp-next5').onclick=()=>{va.pause();stepFrames(va,5,fps);sync()};$$('[data-cskip]').forEach(x=>x.onclick=()=>{va.currentTime=clamp(va.currentTime+(+x.dataset.cskip),0,Math.max(0,(va.duration||999)-.01));sync()});$('#cmp-minus').onclick=()=>{d.offsetFrames--;$('#offset-label').textContent=`${d.offsetFrames}f`;sync()};$('#cmp-plus').onclick=()=>{d.offsetFrames++;$('#offset-label').textContent=`+${d.offsetFrames}f`;sync()};$('#left-anchor-set').onclick=()=>{d.leftAnchor=va.currentTime;$('#left-anchor-label').textContent=fmt(d.leftAnchor,true);sync()};$('#right-anchor-set').onclick=()=>{d.rightAnchor=vb.currentTime;$('#right-anchor-label').textContent=fmt(d.rightAnchor,true);sync()};$('#sync-now').onclick=()=>{va.currentTime=d.leftAnchor;vb.currentTime=d.rightAnchor+offsetSec()};$('#opacity').oninput=e=>{d.opacity=+e.target.value;if(state.compareMode==='overlay')vb.style.opacity=d.opacity};$('#cmp-mirror-right').onchange=e=>{d.mirrorRight=e.target.checked;vb.classList.toggle('mirror',d.mirrorRight)};$('#cmp-speed').onchange=e=>setSpeed(+e.target.value);setSpeed(d.speed||1);$('#cmp-memo').oninput=e=>d.memo=e.target.value;$$('[data-cmode]').forEach(x=>x.onclick=()=>{state.compareMode=x.dataset.cmode;render()});$('#cmp-left-select').onchange=e=>{state.compareLeftId=e.target.value;state.compareDraft=null;render()};$('#cmp-right-select').onchange=e=>{state.compareRightId=e.target.value;state.compareDraft=null;render()};$('#compare-save').onclick=()=>{d.memo=$('#cmp-memo').value;const c={id:uid('cmp'),title:d.title||`${a.title} vs ${b.title}`,leftId:a.id,rightId:b.id,leftAnchor:d.leftAnchor,rightAnchor:d.rightAnchor,offsetFrames:d.offsetFrames,mode:state.compareMode,opacity:d.opacity,mirrorRight:d.mirrorRight,speed:d.speed,memo:d.memo,createdAt:new Date().toISOString()};state.comparisons.push(c);persist('comparisons');toast('比較を保存しました');render()};$$('[data-load-comparison]').forEach(x=>x.onclick=()=>{const c=state.comparisons.find(y=>y.id===x.dataset.loadComparison);state.compareLeftId=c.leftId;state.compareRightId=c.rightId;state.compareMode=c.mode;state.compareDraft={...c};render()})}

function bindSettings(){const upd=(k,val)=>{state.settings[k]=val;persist('settings')};$('#set-back').onchange=e=>upd('skipBack',+e.target.value);$('#set-forward').onchange=e=>upd('skipForward',+e.target.value);$('#set-rewind').onchange=e=>upd('autoRewind',+e.target.value);$('#set-thumb').onchange=e=>upd('thumbDensity',+e.target.value);$('#set-panel').oninput=e=>{upd('panelWidth',+e.target.value);document.documentElement.style.setProperty('--panel-pct',e.target.value+'%')};$('#backup-export').onclick=exportBackup;$('#backup-import').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=importBackup;$('#csv-export').onclick=exportCsv;$('#cache-clear').onclick=()=>toast('表示中サムネイルは画面再読込で再生成されます');$('#reset-data').onclick=()=>{DBKEYS.forEach(k=>localStorage.removeItem('ps2_'+k));location.reload()}}
function exportBackup(){const payload={version:2,exportedAt:new Date().toISOString(),data:Object.fromEntries(DBKEYS.map(k=>[k,state[k]]))};dl(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`playstudy-backup-${new Date().toISOString().slice(0,10)}.json`)}
async function importBackup(e){const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text());if(!x.data)throw Error('bad');DBKEYS.forEach(k=>{if(x.data[k]!=null){state[k]=x.data[k];persist(k)}});state.videos.forEach(v=>{if(v.storageMode==='indexeddb'){v.src='';v.missingSource=true}});persist('videos');toast('復元しました。ローカル動画は再関連付けしてください');setTimeout(()=>location.reload(),600)}catch{toast('バックアップ形式を読み込めません')}}
function csvCell(s){return `"${String(s??'').replaceAll('"','""')}"`}
function exportCsv(){const rows=[['type','video','title','start','end','tag','time']];state.scenes.forEach(s=>rows.push(['scene',video(s.videoId)?.title,s.title,s.start,s.end,tagNames(s.tagIds),'']));state.tagEvents.forEach(t=>rows.push(['tag',video(t.videoId)?.title,'',t.start??'',t.end??'',state.tagDefs.find(d=>d.id===t.tagId)?.name,t.time]));const csv='\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\n');dl(new Blob([csv],{type:'text/csv;charset=utf-8'}),'playstudy-scenes-tags.csv')}

/* ===== v0.3 specification-completion overrides ===== */
function noteKinds(){return state.settings.noteKinds||deep(SEED.settings.noteKinds)}
function noteKindColor(name){return noteKinds().find(k=>k.name===name)?.color||'#64748b'}
function applyTheme(){document.documentElement.dataset.theme=state.settings.theme||'light';document.documentElement.style.colorScheme=state.settings.theme==='dark'?'dark':'light'}
function durationSeconds(v){if(Number.isFinite(v?.durationSeconds))return v.durationSeconds;const p=String(v?.durationLabel||'0:00').split(':').map(Number);return p.length===2?p[0]*60+p[1]:0}
function currentDrawings(videoId,t){return state.drawings.filter(d=>d.videoId===videoId&&t>=d.start&&t<=d.end)}
function dataUrlFromVideo(vid,v,withDrawings=true,withTime=false){const c=document.createElement('canvas');c.width=vid.videoWidth||1280;c.height=vid.videoHeight||720;const ctx=c.getContext('2d');ctx.save();if(v.mirror){ctx.translate(c.width,0);ctx.scale(-1,1)}ctx.drawImage(vid,0,0,c.width,c.height);ctx.restore();if(withDrawings)currentDrawings(v.id,vid.currentTime).forEach(d=>drawShape(ctx,d,c.width,c.height));if(withTime){ctx.save();ctx.font=`${Math.max(18,c.width/55)}px sans-serif`;ctx.fillStyle='rgba(0,0,0,.65)';const text=fmt(vid.currentTime,true);const w=ctx.measureText(text).width+24;ctx.fillRect(12,c.height-52,w,38);ctx.fillStyle='white';ctx.fillText(text,24,c.height-25);ctx.restore()}return c.toDataURL('image/png')}
function makeCompareSourceValue(videoId,sceneId){return sceneId?`s:${sceneId}`:`v:${videoId}`}
function compareSourceOptions(selected){const vids=state.videos.map(v=>`<option value="v:${v.id}" ${selected===`v:${v.id}`?'selected':''}>動画｜${esc(v.title)}</option>`).join('');const scs=state.scenes.map(s=>`<option value="s:${s.id}" ${selected===`s:${s.id}`?'selected':''}>シーン｜${esc(s.title)} (${esc(video(s.videoId)?.title||'')})</option>`).join('');return `<optgroup label="動画">${vids}</optgroup><optgroup label="シーン">${scs}</optgroup>`}
function resolveCompareSource(value,fallbackVideo){if(String(value||'').startsWith('s:')){const s=scene(String(value).slice(2));const v=video(s?.videoId)||fallbackVideo;return{value:`s:${s?.id||''}`,video:v,scene:s,label:s?.title||v?.title||'',start:s?.start||0,end:s?.end??durationSeconds(v)}}const id=String(value||'').replace(/^v:/,'');const v=video(id)||fallbackVideo;return{value:`v:${v?.id||''}`,video:v,scene:null,label:v?.title||'',start:0,end:durationSeconds(v)}}
function normalizeOrders(themeId,lane){state.researchCards.filter(c=>c.themeId===themeId&&c.lane===lane).sort((a,b)=>(a.order||0)-(b.order||0)).forEach((c,i)=>c.order=i+1)}
function setPlaybackAudioPolicy(vid){const policy=state.settings.lowSpeedAudio||'pitch';const slow=(vid.playbackRate||1)<1;if(policy==='mute'&&slow)vid.muted=true;else vid.muted=false;try{vid.preservesPitch=policy!=='normal';vid.webkitPreservesPitch=policy!=='normal'}catch{}}
function player(){const v=activeV();const notes=state.notes.filter(n=>n.videoId===v.id);const fps=v.fps||state.settings.frameRate;const noSource=v.missingSource||(!v.src&&!['indexeddb','handle'].includes(v.storageMode));const as=scene(v.activeSceneId);return `<div class="app-shell player-page ${state.panelCollapsed?'panel-collapsed':''}">${topbar(v.title,true,`<span class="mode-pill">${state.playerMode==='precision'?'精密':'タグ'}モード</span>${as?`<span class="mode-pill scene-active">${esc(as.title)}</span>`:''}`)}<main class="player-wrap"><div class="player-grid"><section class="player-main"><div class="video-stage ${noSource?'no-source':''} ${v.fitMode==='fill'?'video-fill':''}">${noSource?`<div class="missing-source"><b>元動画が見つかりません</b><span>メモ・シーン・研究データは保持されています。</span><button class="btn primary" id="player-relink">再関連付け</button></div>`:`<video id="main-video" src="${videoSrc(v)}" poster="${v.poster||''}" playsinline preload="metadata" class="${v.mirror?'mirror':''}"></video><canvas id="draw-canvas" class="draw-canvas ${state.drawMode?'active':''}"></canvas><div class="video-overlay"><button id="center-play" class="center-play">▶</button><div class="video-time"><span id="time-now">${fmt(v.last||0,true)}</span> / <span id="time-total">--:--</span></div>${state.drawMode?'<div class="draw-badge">描画中</div>':''}</div>`}</div>${noSource?'':timelineHtml(v)}${noSource?'':playerControls(v,fps)}${noSource?'':playerTools(v)}</section>${state.panelCollapsed?'<button class="panel-restore" id="panel-restore">‹ メモ</button>':analysisPanel(notes)}</div></main>${nav()}${noteDialog()}${sceneDialog()}${tagManageDialog()}${drawingDialog()}<div id="toast" class="toast"></div></div>`}
function timelineHtml(v){const zoom=clamp(v.timelineZoom||state.settings.timelineZoom||1,1,8);return `<div class="timeline-card"><div class="timeline-legend"><span><i class="legend-dot" style="background:var(--blue)"></i>メモ</span><span><i class="legend-dot" style="background:var(--purple)"></i>シーン</span><span><i class="legend-dot" style="background:var(--green)"></i>A-B</span><button class="timeline-nav-btn" data-jump-kind="memo" data-jump-dir="-1">‹メモ</button><button class="timeline-nav-btn" data-jump-kind="memo" data-jump-dir="1">メモ›</button><button class="timeline-nav-btn" data-jump-kind="scene" data-jump-dir="-1">‹シーン</button><button class="timeline-nav-btn" data-jump-kind="scene" data-jump-dir="1">シーン›</button><span class="grow"></span><button class="timeline-nav-btn" id="timeline-zoom-out">−</button><span class="subtle" id="timeline-zoom-label">${zoom.toFixed(1)}x</span><button class="timeline-nav-btn" id="timeline-zoom-in">＋</button><button class="link-btn" id="thumb-refresh">更新</button></div><div class="timeline-scroll" id="timeline-scroll"><div class="timeline-inner" id="timeline-hit" style="width:${zoom*100}%"><div id="timeline-scale" class="timeline-scale"></div><div id="marker-layer" class="marker-layer"></div><div class="filmstrip" id="filmstrip" style="--thumb-count:${state.settings.thumbDensity||10}">${Array(state.settings.thumbDensity||10).fill(0).map((_,i)=>`<div class="filmframe" data-thumb="${i}" style="background-image:url('${(v.thumbnails||[])[i]||v.poster||'assets/demo_frame.jpg'}')" ${(v.thumbnails||[])[i]?'data-done="1"':''}></div>`).join('')}</div></div></div><div class="timeline-hint">ピンチで時間軸を拡大。シーン帯の左右端をドラッグして範囲を調整。</div></div>`}
function playerControls(v,fps){const ab=v.ab||{};const lc=ab.loopCount??state.settings.loopCount??0;return `<div class="controls player-controls"><button class="ctrl" data-skip="-${state.settings.skipBack}">↶<small>${state.settings.skipBack}秒</small></button><button class="ctrl" data-frame="-1">|◀</button><button class="ctrl main" id="play-btn">▶</button><button class="ctrl" data-frame="1">▶|</button><button class="ctrl" data-skip="${state.settings.skipForward}">↷<small>${state.settings.skipForward}秒</small></button><button class="ctrl secondary-inline" id="a-btn">A<small>${ab.a==null?'設定':fmt(ab.a,true)}</small></button><button class="ctrl secondary-inline" id="b-btn">B<small>${ab.b==null?'設定':fmt(ab.b,true)}</small></button><button class="ctrl secondary-inline" id="speed-btn">速度<small>${v.lastSpeed||1}x</small></button></div><div class="ab-fine"><span>A</span><button data-ab-adjust="a,-1">-1f</button><b>${ab.a==null?'--':fmt(ab.a,true)}</b><button data-ab-adjust="a,1">+1f</button><span>B</span><button data-ab-adjust="b,-1">-1f</button><b>${ab.b==null?'--':fmt(ab.b,true)}</b><button data-ab-adjust="b,1">+1f</button><label>ループ <select id="ab-loop-count"><option value="0" ${lc===0?'selected':''}>∞</option>${[1,2,3,5,10].map(x=>`<option value="${x}" ${lc===x?'selected':''}>${x}回</option>`).join('')}</select></label><label><input type="checkbox" id="ab-stop-end" ${ab.stopAtEnd!==false?'checked':''}>終了位置で停止</label><span class="subtle">${fps}fps基準</span></div>`}
function playerTools(v){const fav=state.settings.favoriteSpeeds||[.25,.5,1];return `<div class="tools"><button class="tool" data-frame="-5">-5フレーム</button><button class="tool" data-frame="5">+5フレーム</button>${fav.map(x=>`<button class="tool speed-fav ${Math.abs((v.lastSpeed||1)-x)<.001?'active':''}" data-fav-speed="${x}">${x}x</button>`).join('')}<button class="tool" id="mode-toggle">${state.playerMode==='precision'?'タグモードへ':'精密モードへ'}</button><button class="tool portrait-secondary" id="speed-tool">速度 ${v.lastSpeed||1}x</button><button class="tool portrait-secondary" id="a-tool">A点</button><button class="tool portrait-secondary" id="b-tool">B点</button><button class="tool" id="ab-clear">A-B解除</button><button class="tool" id="save-scene">シーン保存</button><button class="tool" id="note-open">メモ</button><button class="tool ${state.drawMode?'active':''}" id="draw-toggle">描画/計測</button><button class="tool ${v.mirror?'active':''}" id="mirror-toggle">反転</button><button class="tool" id="zoom-toggle">拡大 ${v.zoom||1}x</button><button class="tool" id="fit-toggle">${v.fitMode==='fill'?'全体表示':'画面いっぱい'}</button><button class="tool" id="rotate-toggle">回転 ${v.rotation||0}°</button><button class="tool" id="screenshot-btn">静止画</button><button class="tool" id="compare-open">比較</button></div>`}
function kindClass(k){return ''}
function memoList(notes){return notes.length?notes.sort((a,b)=>(a.time||a.start)-(b.time||b.start)).map(n=>{const v=video(n.videoId);const tags=tagNames(n.tagIds);return `<article class="memo-card with-thumb" data-seek="${n.time??n.start??0}"><div class="memo-top"><span>${n.type==='range'?fmt(n.start,true)+' – '+fmt(n.end,true):fmt(n.time,true)}</span><span class="memo-kind" style="background:${noteKindColor(n.kind)}18;color:${noteKindColor(n.kind)}">${esc(n.kind)}</span><button class="icon-mini grow-right" data-edit-note="${n.id}">⋮</button></div><h4>${esc(n.title)}</h4><p>${esc(n.body||'')}</p><div class="memo-links">${tags!=='タグなし'?`<span>${esc(tags)}</span>`:''}${n.themeId?`<span>研究:${esc(theme(n.themeId)?.title||'')}</span>`:''}${n.relatedSceneId?`<span>関連シーン</span>`:''}${(n.drawingIds||[]).length?`<span>描画 ${(n.drawingIds||[]).length}</span>`:''}</div><div class="memo-thumb" style="${n.snapshot?`background-image:url('${n.snapshot}')`:thumbStyle(v,n.time??n.start)}"></div></article>`}).join(''):'<div class="empty">まだメモがありません</div>'}
function tagPanel(){const groups=[...new Set(state.tagDefs.map(t=>t.group||'基本'))];if(!groups.includes(state.settings.activeTagGroup))state.settings.activeTagGroup=groups[0]||'基本';const defs=[...state.tagDefs].filter(t=>(t.group||'基本')===state.settings.activeTagGroup).sort((a,b)=>a.order-b.order).slice(0,12);return `<div class="tag-group-row">${groups.map(g=>`<button class="chip ${g===state.settings.activeTagGroup?'active':''}" data-tag-group="${esc(g)}">${esc(g)}</button>`).join('')}</div><div class="quick-tags">${defs.map(t=>`<button class="tag-btn" data-quicktag="${t.id}" style="--tag-color:${t.color}"><i></i>${esc(t.name)}<small>${t.mode==='point'?'時点':t.mode==='auto'?`前${t.before}/後${t.after}秒`:state.tagStarts[t.id]!=null?'終了待ち':'開始/終了'}</small></button>`).join('')}</div><div class="tag-panel-foot"><button class="link-btn" id="undo-tag">直前タグを取り消す</button><button class="link-btn" id="manage-tags">タグ設定</button></div>`}
function noteDialog(){const n=state.notes.find(x=>x.id===state.editNoteId);return `<dialog id="note-dialog"><div class="dialog-head"><h3>${n?'メモを編集':'メモを追加'}</h3><button class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="field"><label>種別</label><select id="note-kind">${noteKinds().map(k=>`<option ${n?.kind===k.name?'selected':''}>${esc(k.name)}</option>`).join('')}</select></div><div class="field"><label>タイトル</label><input id="note-title" value="${esc(n?.title||'')}" placeholder="短い見出し"></div><div class="field"><label>本文</label><textarea id="note-body" placeholder="気づいたこと">${esc(n?.body||'')}</textarea></div><div class="field"><label>タグ</label><div class="tag-checks">${state.tagDefs.map(t=>`<label><input type="checkbox" data-note-tag="${t.id}" ${(n?.tagIds||[]).includes(t.id)?'checked':''}><i style="background:${t.color}"></i>${esc(t.name)}</label>`).join('')}</div></div><div class="range-fields"><div class="field"><label>関連研究</label><select id="note-theme"><option value="">なし</option>${state.themes.map(t=>`<option value="${t.id}" ${n?.themeId===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div><div class="field"><label>関連シーン</label><select id="note-scene"><option value="">なし</option>${state.scenes.filter(s=>s.videoId===activeV()?.id).map(s=>`<option value="${s.id}" ${n?.relatedSceneId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div></div><label class="check-row"><input id="note-range" type="checkbox" ${n?.type==='range'?'checked':''}> A-B区間に紐付ける（区間メモはシーンも作成）</label><label class="check-row"><input id="note-snapshot" type="checkbox" ${n?.snapshot||(!n&&state.settings.noteAutoSnapshot)?'checked':''}> 現在フレームのスクリーンショットを添付</label><label class="check-row"><input id="note-drawings" type="checkbox" ${(n?.drawingIds||[]).length?'checked':''}> 現在表示中の描画を関連付ける</label>${n?.snapshot?`<img class="note-snapshot-preview" src="${n.snapshot}">`:''}${n?'<button class="btn danger-lite full" id="note-delete">削除</button>':''}</div><div class="dialog-actions"><button class="btn" data-close>キャンセル</button><button class="btn primary" id="note-save">保存</button></div></dialog>`}
function tagManageDialog(){const groups=[...new Set(state.tagDefs.map(t=>t.group||'基本'))];return `<dialog id="tag-dialog"><div class="dialog-head"><h3>クイックタグ設定</h3><button class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="tag-settings-list">${[...state.tagDefs].sort((a,b)=>a.order-b.order).map((t,i)=>`<div class="tag-setting v03" data-tag-setting="${t.id}"><input class="tag-name" value="${esc(t.name)}"><input class="tag-group" value="${esc(t.group||'基本')}" list="tag-groups"><input class="tag-color" type="color" value="${t.color}"><select class="tag-mode"><option value="point" ${t.mode==='point'?'selected':''}>時点</option><option value="auto" ${t.mode==='auto'?'selected':''}>自動区間</option><option value="startend" ${t.mode==='startend'?'selected':''}>開始/終了</option></select><input class="tag-before" type="number" min="0" max="60" value="${t.before||0}" title="前秒"><input class="tag-after" type="number" min="0" max="60" value="${t.after||0}" title="後秒"><button class="icon-mini" data-tag-up="${t.id}">↑</button><button class="icon-mini" data-tag-down="${t.id}">↓</button><button class="icon-mini danger-text" data-tag-delete="${t.id}">×</button></div>`).join('')}</div><datalist id="tag-groups">${groups.map(g=>`<option>${esc(g)}</option>`).join('')}</datalist><button class="btn full" id="tag-add">＋タグ追加</button></div><div class="dialog-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" id="tag-save-all">保存</button></div></dialog>`}
function drawingDialog(){return `<div id="draw-toolbar" class="draw-toolbar ${state.drawMode?'show':''}"><select id="draw-tool"><option value="free" ${state.drawTool==='free'?'selected':''}>フリーハンド</option><option value="line" ${state.drawTool==='line'?'selected':''}>直線</option><option value="arrow" ${state.drawTool==='arrow'?'selected':''}>矢印</option><option value="rect" ${state.drawTool==='rect'?'selected':''}>四角</option><option value="circle" ${state.drawTool==='circle'?'selected':''}>円</option><option value="angle" ${state.drawTool==='angle'?'selected':''}>角度</option><option value="text" ${state.drawTool==='text'?'selected':''}>テキスト</option><option value="eraser" ${state.drawTool==='eraser'?'selected':''}>消しゴム</option></select><input id="draw-text-value" class="draw-text-value" value="${esc(state.drawText||'メモ')}" placeholder="描画テキスト"><select id="draw-life"><option value="frame" ${state.drawLifetime==='frame'?'selected':''}>現在フレーム</option><option value="3s" ${state.drawLifetime==='3s'?'selected':''}>指定秒</option><option value="scene" ${state.drawLifetime==='scene'?'selected':''}>現在シーン</option><option value="manual" ${state.drawLifetime==='manual'?'selected':''}>手動範囲</option></select><input id="draw-duration" type="number" min="0.1" step="0.1" value="${state.drawDuration||3}" title="表示秒"><input id="draw-start" value="${state.drawStart??''}" placeholder="開始秒"><input id="draw-end" value="${state.drawEnd??''}" placeholder="終了秒"><button id="draw-undo">Undo</button><button id="draw-redo">Redo</button><button id="draw-clear">全削除</button><span id="time-measure-label">時間計測 --</span><button id="time-mark-a">時刻A</button><button id="time-mark-b">時刻B</button></div>`}
function drawTimeline(duration,current){const layer=$('#marker-layer');if(!layer||!duration)return;const scale=$('#timeline-scale');scale.innerHTML=[0,.25,.5,.75,1].map(p=>`<span>${fmt(duration*p)}</span>`).join('');const pct=t=>clamp(t/duration*100,0,100);let h='';state.notes.filter(n=>n.videoId===activeV().id).forEach(n=>h+=`<i class="marker note" title="${esc(n.title)}" style="left:${pct(n.time??n.start)}%"></i>`);state.scenes.filter(s=>s.videoId===activeV().id).forEach(s=>{h+=`<div class="scene-span" data-scene-span="${s.id}" style="left:${pct(s.start)}%;width:${Math.max(.2,pct(s.end)-pct(s.start))}%"><button class="scene-edge start" data-scene-edge="start" data-scene-id="${s.id}" title="開始をドラッグ"></button><button class="scene-edge end" data-scene-edge="end" data-scene-id="${s.id}" title="終了をドラッグ"></button></div><i class="marker scene" title="${esc(s.title)}" style="left:${pct(s.start)}%"></i>`});state.tagEvents.filter(t=>t.videoId===activeV().id).forEach(t=>{const d=state.tagDefs.find(x=>x.id===t.tagId);h+=`<i class="marker tag" style="left:${pct(t.time)}%;--marker-color:${d?.color||'#f59e0b'}"></i>`});const ab=activeV().ab||{};if(ab.a!=null&&ab.b!=null)h+=`<div class="ab-range" style="left:${pct(ab.a)}%;width:${Math.max(0,pct(ab.b)-pct(ab.a))}%"></div>`;h+=`<div class="playhead" data-time="${fmt(current,true)}" style="left:${pct(current)}%"></div>`;layer.innerHTML=h}
function drawingLifetime(t,videoId){if(state.drawLifetime==='3s')return{start:t,end:t+(+state.drawDuration||3)};if(state.drawLifetime==='manual'){const a=secsFromInput(state.drawStart),b=secsFromInput(state.drawEnd);if(b>a)return{start:a,end:b}}if(state.drawLifetime==='scene'){const s=state.scenes.find(s=>s.videoId===videoId&&t>=s.start&&t<=s.end);if(s)return{start:s.start,end:s.end}}const fps=video(videoId)?.fps||30;return{start:t-1/fps/2,end:t+1/fps/2}}
function drawShape(ctx,d,w,h){const pts=(d.points||[]).map(p=>({x:p.x*w,y:p.y*h}));ctx.save();ctx.strokeStyle=d.color||'#ff3b30';ctx.fillStyle=d.color||'#ff3b30';ctx.lineWidth=(d.width||3)*devicePixelRatio;ctx.lineCap='round';ctx.lineJoin='round';if(d.type==='text'&&pts[0]){ctx.font=`${Math.max(16,(d.fontSize||20)*devicePixelRatio)}px sans-serif`;ctx.fillText(d.text||'メモ',pts[0].x,pts[0].y);ctx.restore();return}if(!pts.length){ctx.restore();return}if(d.type==='free'){ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);pts.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.stroke()}else if(d.type==='line'||d.type==='arrow'){const a=pts[0],b=pts.at(-1);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(d.type==='arrow'){const ang=Math.atan2(b.y-a.y,b.x-a.x),len=14*devicePixelRatio;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-len*Math.cos(ang-.5),b.y-len*Math.sin(ang-.5));ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-len*Math.cos(ang+.5),b.y-len*Math.sin(ang+.5));ctx.stroke()}}else if(d.type==='rect'){const a=pts[0],b=pts.at(-1);ctx.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y)}else if(d.type==='circle'){const a=pts[0],b=pts.at(-1),rx=Math.abs(b.x-a.x)/2,ry=Math.abs(b.y-a.y)/2;ctx.beginPath();ctx.ellipse((a.x+b.x)/2,(a.y+b.y)/2,rx,ry,0,0,Math.PI*2);ctx.stroke()}else if(d.type==='angle'&&pts.length>=3){ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);ctx.lineTo(pts[1].x,pts[1].y);ctx.lineTo(pts[2].x,pts[2].y);ctx.stroke();ctx.font=`${14*devicePixelRatio}px sans-serif`;ctx.fillText(`${Math.round(d.angle||calcAngle(d.points[0],d.points[1],d.points[2]))}°`,pts[1].x+8,pts[1].y-8)}ctx.restore()}
function bindDrawing(vid,v){const c=$('#draw-canvas');if(!c)return;const stage=c.parentElement;const setup=()=>{const r=stage.getBoundingClientRect();c.width=Math.max(1,r.width*devicePixelRatio);c.height=Math.max(1,r.height*devicePixelRatio);c.style.width=r.width+'px';c.style.height=r.height+'px';redrawDrawings(vid.currentTime)};setup();window.addEventListener('resize',setup,{once:true});$('#draw-tool')?.addEventListener('change',e=>{state.drawTool=e.target.value;$('#draw-text-value').style.display=e.target.value==='text'?'block':''});$('#draw-life')?.addEventListener('change',e=>state.drawLifetime=e.target.value);$('#draw-duration')?.addEventListener('change',e=>state.drawDuration=+e.target.value||3);$('#draw-start')?.addEventListener('input',e=>state.drawStart=e.target.value);$('#draw-end')?.addEventListener('input',e=>state.drawEnd=e.target.value);$('#draw-text-value')?.addEventListener('input',e=>state.drawText=e.target.value);$('#draw-undo')?.addEventListener('click',()=>undoDrawing(v.id));$('#draw-redo')?.addEventListener('click',()=>redoDrawing(v.id));$('#draw-clear')?.addEventListener('click',()=>{const removed=state.drawings.filter(d=>d.videoId===v.id);state.drawingUndo.push(removed);state.drawings=state.drawings.filter(d=>d.videoId!==v.id);persist('drawings');redrawDrawings(vid.currentTime)});$('#time-mark-a')?.addEventListener('click',()=>{state.measureA=vid.currentTime;updateTimeMeasure()});$('#time-mark-b')?.addEventListener('click',()=>{state.measureB=vid.currentTime;updateTimeMeasure()});if(!state.drawMode)return;let pts=[],down=false;const norm=e=>{const r=c.getBoundingClientRect();return{x:clamp((e.clientX-r.left)/r.width,0,1),y:clamp((e.clientY-r.top)/r.height,0,1)}};c.onpointerdown=e=>{const p=norm(e);if(state.drawTool==='eraser'){eraseAt(p,v.id,vid.currentTime);return}if(state.drawTool==='text'){const life=drawingLifetime(vid.currentTime,v.id);state.drawings.push({id:uid('dr'),videoId:v.id,type:'text',points:[p],text:state.drawText||'メモ',fontSize:20,color:'#ff3b30',width:3,start:life.start,end:life.end});persist('drawings');redrawDrawings(vid.currentTime);return}down=true;pts=[p];c.setPointerCapture?.(e.pointerId)};c.onpointermove=e=>{if(!down)return;pts.push(norm(e));previewDrawing(c,vid.currentTime,{type:state.drawTool,points:pts,color:'#ff3b30',width:3})};c.onpointerup=e=>{if(!down)return;down=false;pts.push(norm(e));if(pts.length<2)return;const life=drawingLifetime(vid.currentTime,v.id);const item={id:uid('dr'),videoId:v.id,type:state.drawTool,points:state.drawTool==='free'?pts:[pts[0],pts[pts.length-1]],color:'#ff3b30',width:3,start:life.start,end:life.end};if(state.drawTool==='angle'){item.points=[pts[0],pts[Math.floor(pts.length/2)],pts[pts.length-1]];item.angle=calcAngle(...item.points)}state.drawings.push(item);state.drawingRedo=[];persist('drawings');redrawDrawings(vid.currentTime)}}
