function bindSettings(){const upd=(k,val)=>{state.settings[k]=val;persist('settings')};$('#set-back').onchange=e=>upd('skipBack',+e.target.value);$('#set-forward').onchange=e=>upd('skipForward',+e.target.value);$('#set-rewind').onchange=e=>upd('autoRewind',+e.target.value);$('#set-low-audio').onchange=e=>upd('lowSpeedAudio',e.target.value);$$('[data-fav-speed-setting]').forEach(x=>x.onchange=e=>{state.settings.favoriteSpeeds[+x.dataset.favSpeedSetting]=+e.target.value;persist('settings')});$('#set-note-pause').onchange=e=>upd('notePause',e.target.checked);$('#set-auto-before').onchange=e=>upd('autoBefore',+e.target.value||0);$('#set-auto-after').onchange=e=>upd('autoAfter',+e.target.value||0);$('#set-theme').onchange=e=>{upd('theme',e.target.value);applyTheme()};$('#set-fit').onchange=e=>{upd('fitMode',e.target.value);state.videos.forEach(v=>v.fitMode=e.target.value);persist('videos')};$('#set-thumb').onchange=e=>upd('thumbDensity',+e.target.value);$('#set-panel').oninput=e=>{upd('panelWidth',+e.target.value);document.documentElement.style.setProperty('--panel-pct',e.target.value+'%')};$('#set-img-draw').onchange=e=>upd('exportImageDrawings',e.target.checked);$('#set-img-time').onchange=e=>upd('exportImageTime',e.target.checked);$('#set-clip-speed').onchange=e=>upd('clipSpeed',+e.target.value);$('#set-clip-draw').onchange=e=>upd('clipDrawings',e.target.checked);$('#set-clip-audio').onchange=e=>upd('clipAudio',e.target.checked);$('#note-kind-add').onclick=()=>{state.settings.noteKinds.push({name:'新しい種別',color:COLORS[state.settings.noteKinds.length%COLORS.length]});persist('settings');render()};$$('[data-note-kind-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.noteKindUp,j=Math.max(0,i-1);[state.settings.noteKinds[i],state.settings.noteKinds[j]]=[state.settings.noteKinds[j],state.settings.noteKinds[i]];persist('settings');render()});$$('[data-note-kind-down]').forEach(b=>b.onclick=()=>{const i=+b.dataset.noteKindDown,j=Math.min(state.settings.noteKinds.length-1,i+1);[state.settings.noteKinds[i],state.settings.noteKinds[j]]=[state.settings.noteKinds[j],state.settings.noteKinds[i]];persist('settings');render()});$$('[data-note-kind-delete]').forEach(b=>b.onclick=()=>{state.settings.noteKinds.splice(+b.dataset.noteKindDelete,1);persist('settings');render()});$$('[data-note-kind-name]').forEach(x=>x.onchange=e=>{state.settings.noteKinds[+x.dataset.noteKindName].name=e.target.value.trim()||'種別';persist('settings')});$$('[data-note-kind-color]').forEach(x=>x.onchange=e=>{state.settings.noteKinds[+x.dataset.noteKindColor].color=e.target.value;persist('settings')});$('#backup-export').onclick=()=>exportBackup(false);$('#backup-export-videos').onclick=()=>exportBackup(true);$('#backup-import').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=importBackup;$('#csv-export').onclick=exportCsv;$('#cache-clear').onclick=()=>{state.videos.forEach(v=>delete v.thumbnails);persist('videos');toast('サムネイルキャッシュを削除しました')};$('#reset-data').onclick=()=>{DBKEYS.forEach(k=>localStorage.removeItem('ps2_'+k));location.reload()}}
function blobToDataURL(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)})}
function dataURLToBlob(data){const [head,body]=data.split(','),mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream',bin=atob(body),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);return new Blob([arr],{type:mime})}
async function exportBackup(includeVideos=false){const payload={version:3,exportedAt:new Date().toISOString(),includeVideos,data:Object.fromEntries(DBKEYS.map(k=>[k,state[k]])),videoFiles:{}};if(includeVideos){toast('動画をバックアップへまとめています');for(const v of state.videos){try{let blob=null;if(v.storageMode==='opfs')blob=await opfsGet(v.id);else if(v.storageMode==='indexeddb')blob=await idbGet(v.id);else if(v.storageMode==='handle')blob=await (await idbGetHandle(v.id))?.getFile();else if(v.src)blob=await (await fetch(v.src)).blob();if(blob)payload.videoFiles[v.id]={name:v.fileName||(v.title||v.id)+'.'+((v.mimeType||blob.type||'video/mp4').split('/')[1]||'mp4'),type:v.mimeType||blob.type,data:await blobToDataURL(blob)}}catch(e){console.warn('backup video skip',v.id,e)}}}dl(new Blob([JSON.stringify(payload)],{type:'application/json'}),`playstudy-${includeVideos?'with-videos':'analysis'}-${new Date().toISOString().slice(0,10)}.${includeVideos?'psbundle':'json'}`)}
async function importBackup(e){const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text());if(!x.data)throw Error('bad');DBKEYS.forEach(k=>{if(x.data[k]!=null){state[k]=x.data[k];persist(k)}});if(x.videoFiles){for(const [id,obj] of Object.entries(x.videoFiles)){const blob=dataURLToBlob(obj.data),file=new File([blob],obj.name||id,{type:obj.type||blob.type}),stored=await storeVideoFile(id,file),v=state.videos.find(v=>v.id===id);if(v){v.src='';v.storageMode=stored.mode;v.fileName=file.name;v.mimeType=file.type;v.missingSource=false}}}else state.videos.forEach(v=>{if(STORED_VIDEO_MODES.has(v.storageMode)){v.src='';v.missingSource=true}});persist('videos');toast('復元しました');setTimeout(()=>location.reload(),400)}catch(err){console.error(err);toast('バックアップ形式を読み込めません')}}
async function exportCurrentFrame(vid,v){try{const data=dataUrlFromVideo(vid,v,state.settings.exportImageDrawings!==false,state.settings.exportImageTime===true);const blob=await (await fetch(data)).blob();dl(blob,`${v.title}_${fmt(vid.currentTime,true).replace(':','-')}.png`)}catch(e){toast('静止画を書き出せませんでした')}}
async function exportSceneClip(s){const v=video(s.videoId);await hydrateVideo(v);if(!v.src)return toast('元動画を再関連付けしてください');const temp=document.createElement('video');temp.src=v.src;temp.playsInline=true;temp.preload='auto';temp.style.cssText='position:fixed;width:1px;height:1px;opacity:0;pointer-events:none';document.body.appendChild(temp);await new Promise((res,rej)=>{temp.onloadedmetadata=res;temp.onerror=rej});temp.currentTime=s.start;await new Promise(res=>temp.addEventListener('seeked',res,{once:true}));const speed=state.settings.clipSpeed||1;temp.playbackRate=speed;try{temp.preservesPitch=state.settings.clipSlowAudio!=='normal'}catch{};const c=document.createElement('canvas');c.width=temp.videoWidth||1280;c.height=temp.videoHeight||720;const ctx=c.getContext('2d'),canvasStream=c.captureStream(30);let tracks=[...canvasStream.getVideoTracks()];if(state.settings.clipAudio&&temp.captureStream){const source=temp.captureStream();tracks.push(...source.getAudioTracks())}const stream=new MediaStream(tracks),mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm',rec=new MediaRecorder(stream,{mimeType:mime}),chunks=[];rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=()=>{dl(new Blob(chunks,{type:'video/webm'}),`${s.title}_${speed}x.webm`);temp.remove();canvasStream.getTracks().forEach(t=>t.stop());toast('クリップを書き出しました')};rec.start();const draw=()=>{if(temp.currentTime>=s.end||temp.ended){temp.pause();rec.stop();return}ctx.drawImage(temp,0,0,c.width,c.height);if(state.settings.clipDrawings)currentDrawings(v.id,temp.currentTime).forEach(d=>drawShape(ctx,d,c.width,c.height));requestAnimationFrame(draw)};await temp.play();draw();toast(`${speed}xでクリップを書き出しています`)}
let videoDbPromise=null;
function idb(){if(videoDbPromise)return videoDbPromise;videoDbPromise=new Promise((res,rej)=>{const r=indexedDB.open('playstudy_v2',3);r.onupgradeneeded=()=>{for(const name of ['videos','shared','handles'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name)};r.onsuccess=()=>{const db=r.result;db.onversionchange=()=>{db.close();videoDbPromise=null};res(db)};r.onerror=()=>{videoDbPromise=null;rej(r.error)};r.onblocked=()=>{videoDbPromise=null;rej(new Error('動画保存領域を開けませんでした'))}});return videoDbPromise}
async function idbPutHandle(id,handle){const db=await idb();return new Promise((res,rej)=>{const tx=db.transaction('handles','readwrite');tx.objectStore('handles').put(handle,id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function idbGetHandle(id){const db=await idb();return new Promise((res,rej)=>{const r=db.transaction('handles').objectStore('handles').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function opfsDirectory(){if(!navigator.storage?.getDirectory)throw new Error('OPFS unavailable');const root=await navigator.storage.getDirectory();return root.getDirectoryHandle('playstudy-videos',{create:true})}
async function opfsPut(id,file){const directory=await opfsDirectory(),handle=await directory.getFileHandle(id,{create:true}),writable=await handle.createWritable();try{await writable.write(file);await writable.close()}catch(error){try{await writable.abort?.()}catch{}throw error}const stored=await handle.getFile();if(stored.size!==file.size)throw new Error('動画の保存サイズが一致しません');return stored}
async function opfsGet(id){try{const directory=await opfsDirectory(),handle=await directory.getFileHandle(id);return await handle.getFile()}catch(error){if(error?.name==='NotFoundError')return null;throw error}}
async function opfsDelete(id){try{const directory=await opfsDirectory();await directory.removeEntry(id)}catch(error){if(error?.name!=='NotFoundError')throw error}}
async function idbDeleteRecord(id){const db=await idb();if(!db.objectStoreNames.contains('videos'))return;await new Promise(res=>{const tx=db.transaction('videos','readwrite');tx.objectStore('videos').delete(id);tx.oncomplete=res;tx.onerror=res})}
async function storeVideoFile(id,file){await ensurePersistentStorage();if(navigator.storage?.getDirectory){try{await opfsPut(id,file);return {mode:'opfs'}}catch(error){console.warn('OPFS video save failed, using IndexedDB',error)}}await idbPut(id,file);return {mode:'indexeddb'}}
async function migrateIndexedVideo(v,blob){if(!navigator.storage?.getDirectory||!blob)return;try{await opfsPut(v.id,blob);v.storageMode='opfs';v.fileName=v.fileName||blob.name||v.title;v.mimeType=v.mimeType||blob.type;persist('videos');await idbDeleteRecord(v.id)}catch(error){console.warn('video migration to OPFS failed',error)}}
async function addReferenceVideos(){if(!window.showOpenFilePicker)return toast('このブラウザは参照追加に未対応です');try{const handles=await showOpenFilePicker({multiple:true,types:[{description:'動画',accept:{'video/*':['.mp4','.webm','.mov','.m4v']}}]});for(const h of handles){const file=await h.getFile(),id=uid('v');await idbPutHandle(id,h);const url=URL.createObjectURL(file),meta=await probeVideo(url),fs=state.folders.filter(f=>f.projectId===state.activeProject);state.videos.unshift({id,title:file.name.replace(/\.[^.]+$/,''),date:new Date(file.lastModified||Date.now()).toISOString().slice(0,10),durationLabel:fmt(meta.duration),durationSeconds:meta.duration,src:url,poster:'assets/demo_frame.jpg',projectId:state.activeProject,folderId:state.activeFolder!=='all'?state.activeFolder:(fs[0]?.id||''),favorite:false,last:0,lastSpeed:1,fps:30,athlete:'',opponent:'',eventName:'',storageMode:'handle',missingSource:false})}persist('videos');render()}catch(e){if(e.name!=='AbortError')toast('参照追加に失敗しました')}}
const videoHydrationJobs=new Map();
function attachVideoSource(v,blob){if(v.src?.startsWith('blob:'))URL.revokeObjectURL(v.src);v.src=URL.createObjectURL(blob);v.missingSource=false;return v.src}
async function hydrateVideo(v,force=false){if(!v)return v;if(v.src&&!force)return v;if(!force&&videoHydrationJobs.has(v.id))return videoHydrationJobs.get(v.id);const job=(async()=>{try{if(force&&v.src?.startsWith('blob:'))URL.revokeObjectURL(v.src);if(force)v.src='';if(v.storageMode==='opfs'){const stored=await opfsGet(v.id);if(stored){const blob=stored.type?stored:new File([stored],v.fileName||v.id,{type:v.mimeType||'video/mp4'});attachVideoSource(v,blob)}else v.missingSource=true}else if(v.storageMode==='indexeddb'){const blob=await idbGet(v.id);if(blob){attachVideoSource(v,blob);migrateIndexedVideo(v,blob)}else v.missingSource=true}else if(v.storageMode==='handle'){const h=await idbGetHandle(v.id);if(h){let perm=await h.queryPermission?.({mode:'read'});if(perm==='prompt')perm=await h.requestPermission?.({mode:'read'});if(perm==='granted'||perm==null)attachVideoSource(v,await h.getFile());else v.missingSource=true}else v.missingSource=true}}catch(error){console.warn('stored video hydration failed',error);v.src='';v.missingSource=true}persist('videos');return v})();videoHydrationJobs.set(v.id,job);try{return await job}finally{if(videoHydrationJobs.get(v.id)===job)videoHydrationJobs.delete(v.id)}}
async function ensurePersistentStorage(){try{if(!navigator.storage?.persist)return false;if(await navigator.storage.persisted?.())return true;return await navigator.storage.persist()}catch{return false}}
function library(){const p=project(state.activeProject)||state.projects[0],folders=state.folders.filter(f=>f.projectId===p.id);let vids=state.videos.filter(v=>v.projectId===p.id);if(state.activeFolder!=='all')vids=vids.filter(v=>v.folderId===state.activeFolder);const q=state.query.trim().toLowerCase();if(q)vids=vids.filter(v=>videoSearchHay(v).includes(q));return `<div class="app-shell">${topbar('ライブラリ',false,'<button class="header-action" id="manage-library">整理</button>')}<main class="content"><div class="library-project-row"><button class="project-btn" id="project-switch">▣ ${esc(p.name)}⌄</button><span class="grow"></span>${window.showOpenFilePicker?'<button class="btn compact" id="add-reference">参照で追加</button>':''}</div><div class="search-row"><div class="search">${ICONS.search}<input id="search" placeholder="動画・タグ・メモを検索" value="${esc(state.query)}"></div><button class="filter-btn" id="clear-filter">☷</button></div><div class="chip-row"><button class="chip ${state.activeFolder==='all'?'active':''}" data-folder="all">すべて</button>${folders.map(f=>`<button class="chip ${state.activeFolder===f.id?'active':''}" data-folder="${f.id}">${esc(f.name)}</button>`).join('')}<button class="chip dashed" id="new-folder">＋</button></div><section class="section recent-section" style="margin-top:20px"><div class="section-head"><h3>最近見た動画</h3><span class="subtle">${vids.length}本</span></div><div class="recent-grid">${[...vids].sort((a,b)=>(b.lastOpened||0)-(a.lastOpened||0)).slice(0,2).map(videoCard).join('')||'<div class="empty">動画を追加してください</div>'}</div></section><section class="section"><div class="section-head"><h3>動画一覧</h3><span class="subtle">検索・フォルダ横断対応</span></div><div class="list-stack">${vids.map(videoListCard).join('')||'<div class="empty">一致する動画がありません</div>'}</div></section></main><button class="fab" id="add-video">+</button>${nav()}${projectDialog()}${folderDialog()}${videoMetaDialog()}<div id="toast" class="toast"></div></div>`}
function bindLibrary(){ $('#search').oninput=e=>{state.query=e.target.value;render()};$$('[data-folder]').forEach(b=>b.onclick=()=>{state.activeFolder=b.dataset.folder;render()});$('#clear-filter').onclick=()=>{state.activeFolder='all';state.query='';render()};$('#project-switch').onclick=()=>$('#project-dialog').showModal();$('#manage-library').onclick=()=>$('#project-dialog').showModal();$('#project-create').onclick=()=>{const name=$('#project-name').value.trim();if(!name)return toast('プロジェクト名を入力してください');const p={id:uid('p'),name,sportName:$('#project-sport').value.trim(),description:''};state.projects.push(p);state.activeProject=p.id;state.activeFolder='all';persist('projects');$('#project-dialog').close();render()};$$('[data-pick-project]').forEach(b=>b.onclick=()=>{state.activeProject=b.dataset.pickProject;state.activeFolder='all';$('#project-dialog').close();render()});$('#project-rename').onclick=()=>{const p=project(state.activeProject),name=$('#current-project-name').value.trim();if(name){p.name=name;persist('projects');$('#project-dialog').close();render()}};$('#folder-save-names').onclick=()=>{$$('[data-folder-rename]').forEach(x=>{const f=folder(x.dataset.folderRename);if(f&&x.value.trim())f.name=x.value.trim()});persist('folders');$('#project-dialog').close();render()};$$('[data-folder-delete]').forEach(b=>b.onclick=()=>{const id=b.dataset.folderDelete;if(state.videos.some(v=>v.folderId===id))return toast('動画が入っているフォルダは削除できません');state.folders=state.folders.filter(f=>f.id!==id);persist('folders');render();setTimeout(()=>$('#project-dialog').showModal(),0)});$('#project-delete')?.addEventListener('click',()=>{const id=state.activeProject;if(state.videos.some(v=>v.projectId===id))return toast('動画が入っているプロジェクトは削除できません');state.projects=state.projects.filter(p=>p.id!==id);state.folders=state.folders.filter(f=>f.projectId!==id);state.activeProject=state.projects[0]?.id;persistMany('projects','folders');$('#project-dialog').close();render()});$('#new-folder').onclick=()=>$('#folder-dialog').showModal();$('#folder-create').onclick=()=>{const name=$('#folder-name').value.trim();if(!name)return;state.folders.push({id:uid('f'),projectId:state.activeProject,name});persist('folders');$('#folder-dialog').close();render()};$('#add-video').onclick=()=>$('#video-file').click();$('#add-reference')?.addEventListener('click',addReferenceVideos);const inp=$('#video-file');inp.onchange=handleVideoFiles;bindVideoMeta()}
function bind(){const globalRel=$('#relink-file-global');if(globalRel)globalRel.onchange=e=>{const f=e.target.files[0];if(f&&state.relinkVideoId){relinkFile(f,state.relinkVideoId);e.target.value=''}};$$('[data-nav]').forEach(b=>b.onclick=()=>route(b.dataset.nav));$$('[data-back]').forEach(b=>b.onclick=()=>route(state.screen==='compare'?'player':'library'));$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog')?.close());$$('[data-open-video]').forEach(el=>el.onclick=e=>{if(e.target.closest('button'))return;const v=video(el.dataset.openVideo);if(v&&el.dataset.start!=null){v.last=+el.dataset.start;v.activeSceneId=el.dataset.sceneId||'';persist('videos')}route('player',el.dataset.openVideo)});$$('[data-favorite]').forEach(b=>b.onclick=e=>{e.stopPropagation();const v=video(b.dataset.favorite);v.favorite=!v.favorite;persist('videos');render()});$$('[data-edit-video]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.editVideoId=b.dataset.editVideo;render();setTimeout(()=>$('#video-meta-dialog')?.showModal())});if(state.screen==='library')bindLibrary();if(state.screen==='player')bindPlayer();if(state.screen==='record')bindRecord();if(state.screen==='research')bindResearch();if(state.screen==='compare')bindCompare();if(state.screen==='settings')bindSettings()}
async function consumeSharedVideos(){try{const db=await idb();if(!db.objectStoreNames.contains('shared'))return;const records=await new Promise((res,rej)=>{const r=db.transaction('shared','readwrite').objectStore('shared').getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)});if(!records.length)return;for(const rec of records){const id=uid('v'),stored=await storeVideoFile(id,rec.file),url=URL.createObjectURL(rec.file),meta=await probeVideo(url),fs=state.folders.filter(f=>f.projectId===state.activeProject);state.videos.unshift({id,title:rec.file.name.replace(/\.[^.]+$/,''),fileName:rec.file.name,mimeType:rec.file.type,date:new Date().toISOString().slice(0,10),durationLabel:fmt(meta.duration),durationSeconds:meta.duration,src:url,poster:'assets/demo_frame.jpg',projectId:state.activeProject,folderId:fs[0]?.id||'',favorite:false,last:0,lastSpeed:1,fps:30,athlete:'',opponent:'',eventName:'共有から追加',storageMode:stored.mode,missingSource:false})}const tx=db.transaction('shared','readwrite');tx.objectStore('shared').clear();persist('videos');toast(`${records.length}本を端末に保存しました`);render()}catch(e){console.warn('share import',e)}}


async function idbDelete(id){try{await opfsDelete(id)}catch{}const db=await idb();for(const store of ['videos','handles'])if(db.objectStoreNames.contains(store))await new Promise(res=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=res;tx.onerror=res})}
function bindVideoMeta(){const d=$('#video-meta-dialog');if(!d||!state.editVideoId)return;const v=video(state.editVideoId);$('#vm-project').onchange=e=>{v.projectId=e.target.value;const fs=state.folders.filter(f=>f.projectId===v.projectId);$('#vm-folder').innerHTML=fs.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')};$('#vm-save').onclick=()=>{v.title=$('#vm-title').value.trim()||v.title;v.projectId=$('#vm-project').value;v.folderId=$('#vm-folder').value;v.athlete=$('#vm-athlete').value.trim();v.opponent=$('#vm-opponent').value.trim();v.eventName=$('#vm-event').value.trim();v.fps=clamp(+$(`#vm-fps`).value||30,1,240);persist('videos');d.close();render()};$('#detach-video')?.addEventListener('click',async()=>{if(STORED_VIDEO_MODES.has(v.storageMode))try{await idbDelete(v.id)}catch{}v.src='';v.missingSource=true;persist('videos');d.close();render()});$('#relink-video')?.addEventListener('click',()=>{state.relinkVideoId=v.id;$('#relink-file-global')?.click()})}

/* ===== v0.3 spec-detail completion ===== */
function formatBytes(n){if(!Number.isFinite(n)||n<=0)return '0 MB';if(n<1024*1024)return (n/1024).toFixed(1)+' KB';if(n<1024*1024*1024)return (n/1024/1024).toFixed(1)+' MB';return (n/1024/1024/1024).toFixed(2)+' GB'}
function videoSearchHay(v){const pid=project(v.projectId)?.name||'',fid=folder(v.folderId)?.name||'';const nts=state.notes.filter(n=>n.videoId===v.id).map(n=>n.title+' '+n.body).join(' ');const scs=state.scenes.filter(s=>s.videoId===v.id).map(s=>s.title+' '+(s.memo||'')).join(' ');const tev=state.tagEvents.filter(t=>t.videoId===v.id).map(t=>state.tagDefs.find(d=>d.id===t.tagId)?.name||'').join(' ');const vtags=(v.tagIds||[]).map(id=>state.tagDefs.find(t=>t.id===id)?.name||'').join(' ');return [v.title,pid,fid,v.sportName,v.athlete,v.opponent,v.eventName,v.freeMemo,vtags,nts,scs,tev].join(' ').toLowerCase()}
function videoMetaDialog(){const v=video(state.editVideoId);if(!v)return '<dialog id="video-meta-dialog"></dialog>';const fs=state.folders.filter(f=>f.projectId===v.projectId);return `<dialog id="video-meta-dialog"><div class="dialog-head"><h3>動画情報</h3><button class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="field"><label>動画名</label><input id="vm-title" value="${esc(v.title)}"></div><div class="range-fields"><div class="field"><label>撮影日</label><input id="vm-date" type="date" value="${String(v.date||'').replaceAll('/','-')}"></div><div class="field"><label>競技・種目</label><input id="vm-sport" value="${esc(v.sportName||'')}"></div></div><div class="field"><label>プロジェクト</label><select id="vm-project">${state.projects.map(p=>`<option value="${p.id}" ${p.id===v.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>フォルダ</label><select id="vm-folder">${fs.map(f=>`<option value="${f.id}" ${f.id===v.folderId?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><div class="range-fields"><div class="field"><label>選手・チーム</label><input id="vm-athlete" value="${esc(v.athlete||'')}"></div><div class="field"><label>対戦相手</label><input id="vm-opponent" value="${esc(v.opponent||'')}"></div></div><div class="field"><label>大会・練習名</label><input id="vm-event" value="${esc(v.eventName||'')}"></div><div class="field"><label>動画タグ</label><div class="tag-checks">${state.tagDefs.map(t=>`<label><input type="checkbox" data-video-tag="${t.id}" ${(v.tagIds||[]).includes(t.id)?'checked':''}><i style="background:${t.color}"></i>${esc(t.name)}</label>`).join('')}</div></div><div class="field"><label>自由メモ</label><textarea id="vm-memo">${esc(v.freeMemo||'')}</textarea></div><div class="field"><label>FPS（Web版コマ送り基準）</label><input id="vm-fps" type="number" min="1" max="240" value="${v.fps||state.settings.frameRate}"></div><div class="notice-card"><b>保存方式</b><p>${v.storageMode==='handle'?'元ファイル参照':v.storageMode==='opfs'?'端末に保存済み':v.storageMode==='indexeddb'?'旧形式（自動移行）':'同梱動画'}${v.missingSource?'・元動画なし':''}</p></div>${v.missingSource?'<button class="btn full" id="relink-video">元動画を再関連付け</button>':'<button class="btn full danger-lite" id="detach-video">元動画を切り離す（分析データは残す）</button>'}</div><div class="dialog-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" id="vm-save">保存</button></div></dialog>`}
function bindVideoMeta(){const d=$('#video-meta-dialog');if(!d||!state.editVideoId)return;const v=video(state.editVideoId);$('#vm-project').onchange=e=>{v.projectId=e.target.value;const fs=state.folders.filter(f=>f.projectId===v.projectId);$('#vm-folder').innerHTML=fs.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')};$('#vm-save').onclick=()=>{v.title=$('#vm-title').value.trim()||v.title;v.date=$('#vm-date').value||v.date;v.sportName=$('#vm-sport').value.trim();v.projectId=$('#vm-project').value;v.folderId=$('#vm-folder').value;v.athlete=$('#vm-athlete').value.trim();v.opponent=$('#vm-opponent').value.trim();v.eventName=$('#vm-event').value.trim();v.freeMemo=$('#vm-memo').value.trim();v.tagIds=$$('[data-video-tag]:checked').map(x=>x.dataset.videoTag);v.fps=clamp(+$(`#vm-fps`).value||30,1,240);persist('videos');d.close();render()};$('#detach-video')?.addEventListener('click',async()=>{if(STORED_VIDEO_MODES.has(v.storageMode))try{await idbDelete(v.id)}catch{}v.src='';v.missingSource=true;persist('videos');d.close();render()});$('#relink-video')?.addEventListener('click',()=>{state.relinkVideoId=v.id;$('#relink-file-global')?.click()})}
async function handleVideoFiles(e){const files=[...e.target.files];if(!files.length)return;const added=[];for(const file of files){const id=uid('v');added.push(id);await idbPut(id,file);const url=URL.createObjectURL(file),meta=await probeVideo(url),fs=state.folders.filter(f=>f.projectId===state.activeProject),p=project(state.activeProject);state.videos.unshift({id,title:file.name.replace(/\.[^.]+$/,''),date:new Date(file.lastModified||Date.now()).toISOString().slice(0,10),durationLabel:fmt(meta.duration),durationSeconds:meta.duration,src:url,poster:'assets/demo_frame.jpg',projectId:state.activeProject,folderId:state.activeFolder!=='all'?state.activeFolder:(fs[0]?.id||''),favorite:false,last:0,lastSpeed:1,fps:Math.round(meta.fps||30),sportName:p?.sportName||'',athlete:'',opponent:'',eventName:'',tagIds:[],freeMemo:'',storageMode:'indexeddb',missingSource:false})}persist('videos');e.target.value='';if(state.simpleMode&&added.length===1){state.activeVideo=added[0];route('player',added[0]);toast('動画を開きました')}else{render();toast(`${files.length}本追加しました`)}}
function openNote(vid,id=null){state.editNoteId=id;render();setTimeout(()=>{const d=$('#note-dialog');if(state.settings.notePause&&state.playerMode==='precision')vid?.pause();d?.showModal()},0)}
function sceneDialog(){const s=scene(state.editSceneId);if(!s)return '<dialog id="scene-dialog"></dialog>';const overlap=state.drawings.filter(d=>d.videoId===s.videoId&&d.end>=s.start&&d.start<=s.end).length;return `<dialog id="scene-dialog"><div class="dialog-head"><h3>シーン編集</h3><button class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="field"><label>タイトル</label><input id="scene-title" value="${esc(s.title)}"></div><div class="range-fields"><div class="field"><label>開始（秒 / mm:ss）</label><input id="scene-start" value="${fmt(s.start,true)}"></div><div class="field"><label>終了</label><input id="scene-end" value="${fmt(s.end,true)}"></div></div><label class="check-row"><input id="scene-favorite" type="checkbox" ${s.favorite?'checked':''}> お気に入り</label><div class="field"><label>シーンメモ</label><textarea id="scene-memo">${esc(s.memo||'')}</textarea></div><div class="field"><label>タグ</label><div class="tag-checks">${state.tagDefs.map(t=>`<label><input type="checkbox" data-scene-tag="${t.id}" ${(s.tagIds||[]).includes(t.id)?'checked':''}><i style="background:${t.color}"></i>${esc(t.name)}</label>`).join('')}</div></div><div class="notice-card"><b>関連描画 ${overlap}件</b><p>シーン時間と重なる描画は、再生・書き出し時に自動的に関連付けられます。</p></div><div class="range-fields"><div class="field"><label>研究テーマへ追加</label><select id="scene-theme"><option value="">追加しない</option>${state.themes.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></div><div class="field"><label>プレイリストへ追加</label><select id="scene-playlist"><option value="">追加しない</option>${state.playlists.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></div></div><div class="dialog-action-grid"><button class="btn" id="scene-export">WebMクリップ書き出し</button><button class="btn danger-lite" id="scene-delete">削除</button></div></div><div class="dialog-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" id="scene-save">保存</button></div></dialog>`}
function bindSceneDialogActions(){const s=scene(state.editSceneId),d=$('#scene-dialog');if(!s||!d)return;$('#scene-save').onclick=()=>{const start=secsFromInput($('#scene-start').value),end=secsFromInput($('#scene-end').value);if(end<=start)return toast('終了時刻は開始より後にしてください');s.title=$('#scene-title').value.trim()||s.title;s.start=start;s.end=end;s.memo=$('#scene-memo').value.trim();s.favorite=$('#scene-favorite').checked;s.tagIds=$$('[data-scene-tag]:checked').map(x=>x.dataset.sceneTag);const th=$('#scene-theme').value;if(th&&!state.researchCards.some(c=>c.themeId===th&&c.type==='scene'&&c.refId===s.id))addResearchCard(th,'scene',s.id,theme(th).lanes.find(x=>x!=='未整理')||'未整理');const pl=$('#scene-playlist').value;if(pl){const p=state.playlists.find(x=>x.id===pl);if(p&&!p.items.some(i=>i.sceneId===s.id))p.items.push({sceneId:s.id,loopCount:1});persist('playlists')}persist('scenes');d.close();state.editSceneId=null;render()};$('#scene-delete').onclick=()=>{state.scenes=state.scenes.filter(x=>x.id!==s.id);state.researchCards=state.researchCards.filter(c=>!(c.type==='scene'&&c.refId===s.id));state.playlists.forEach(pl=>pl.items=pl.items.filter(i=>i.sceneId!==s.id));persistMany('scenes','researchCards','playlists');d.close();state.editSceneId=null;render()};$('#scene-export').onclick=()=>exportSceneClip(s)}
function drawTimeline(duration,current){const layer=$('#marker-layer');if(!layer||!duration)return;const scale=$('#timeline-scale');scale.innerHTML=[0,.25,.5,.75,1].map(p=>`<span>${fmt(duration*p)}</span>`).join('');const pct=t=>clamp(t/duration*100,0,100);let h='';state.notes.filter(n=>n.videoId===activeV().id).forEach(n=>{if(n.type==='range'&&n.end!=null)h+=`<div class="memo-span" style="left:${pct(n.start)}%;width:${Math.max(.15,pct(n.end)-pct(n.start))}%"></div>`;h+=`<i class="marker note" data-marker-seek="${n.time??n.start}" title="${esc(n.title)}" style="left:${pct(n.time??n.start)}%"></i>`});state.scenes.filter(s=>s.videoId===activeV().id).forEach(s=>{h+=`<div class="scene-span" data-scene-span="${s.id}" style="left:${pct(s.start)}%;width:${Math.max(.2,pct(s.end)-pct(s.start))}%"><button class="scene-edge start" data-scene-edge="start" data-scene-id="${s.id}" title="開始をドラッグ"></button><button class="scene-edge end" data-scene-edge="end" data-scene-id="${s.id}" title="終了をドラッグ"></button></div><i class="marker scene" data-marker-seek="${s.start}" title="${esc(s.title)}" style="left:${pct(s.start)}%"></i>`});state.tagEvents.filter(t=>t.videoId===activeV().id).forEach(t=>{const d=state.tagDefs.find(x=>x.id===t.tagId);h+=`<i class="marker tag" data-marker-seek="${t.time}" title="${esc(d?.name||'タグ')}" style="left:${pct(t.time)}%;--marker-color:${d?.color||'#f59e0b'}"></i>`});state.drawings.filter(d=>d.videoId===activeV().id).forEach(d=>h+=`<div class="drawing-span" title="描画" style="left:${pct(d.start)}%;width:${Math.max(.12,pct(d.end)-pct(d.start))}%"></div>`);const ab=activeV().ab||{};if(ab.a!=null&&ab.b!=null)h+=`<div class="ab-range" style="left:${pct(ab.a)}%;width:${Math.max(0,pct(ab.b)-pct(ab.a))}%"></div>`;h+=`<div class="playhead" data-time="${fmt(current,true)}" style="left:${pct(current)}%"></div>`;layer.innerHTML=h}
function bindTimelineGestures(vid,v){const inner=$('#timeline-hit'),scroll=$('#timeline-scroll'),layer=$('#marker-layer');if(!inner||!scroll)return;const pointers=new Map();let pinch=null;inner.style.touchAction='pan-x';inner.onpointerdown=e=>{if(e.target.closest('[data-scene-edge]'))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const a=[...pointers.values()];pinch={dist:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),zoom:v.timelineZoom||1};inner.style.touchAction='none'}};inner.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const a=[...pointers.values()],dist=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);v.timelineZoom=clamp(pinch.zoom*dist/(pinch.dist||1),1,8);inner.style.width=(v.timelineZoom*100)+'%';$('#timeline-zoom-label').textContent=v.timelineZoom.toFixed(1)+'x'}};const up=e=>{pointers.delete(e.pointerId);if(pointers.size<2){pinch=null;inner.style.touchAction='pan-x';persist('videos')}};inner.onpointerup=up;inner.onpointercancel=up;$('#timeline-zoom-in')?.addEventListener('click',()=>{v.timelineZoom=clamp((v.timelineZoom||1)*1.5,1,8);persist('videos');render()});$('#timeline-zoom-out')?.addEventListener('click',()=>{v.timelineZoom=clamp((v.timelineZoom||1)/1.5,1,8);persist('videos');render()});layer?.addEventListener('click',e=>{const m=e.target.closest('[data-marker-seek]');if(m){e.stopPropagation();seek(vid,+m.dataset.markerSeek)}});layer?.addEventListener('pointerdown',e=>{const edge=e.target.closest('[data-scene-edge]');if(!edge)return;e.preventDefault();e.stopPropagation();vid.pause();const s=scene(edge.dataset.sceneId),which=edge.dataset.sceneEdge;if(!s)return;const move=ev=>{const r=inner.getBoundingClientRect(),t=clamp((ev.clientX-r.left)/r.width*vid.duration,0,vid.duration);if(which==='start')s.start=Math.min(t,s.end-.02);else s.end=Math.max(t,s.start+.02);drawTimeline(vid.duration,vid.currentTime)};const done=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',done);persist('scenes')};window.addEventListener('pointermove',move);window.addEventListener('pointerup',done,{once:true})})}
function thumbCacheBytes(){return state.videos.reduce((sum,v)=>sum+(v.thumbnails||[]).reduce((x,s)=>x+Math.ceil(String(s||'').length*.75),0),0)}
function enforceThumbCacheLimit(){const max=(state.settings.thumbCacheLimitMB||25)*1024*1024;let total=thumbCacheBytes();if(total<=max)return;const vids=[...state.videos].sort((a,b)=>(a.lastOpened||0)-(b.lastOpened||0));for(const v of vids){if(total<=max)break;const n=(v.thumbnails||[]).reduce((x,s)=>x+Math.ceil(String(s||'').length*.75),0);if(n){delete v.thumbnails;total-=n}}persist('videos')}
async function refreshStorageEstimate(){const el=$('#storage-estimate');if(!el)return;let used=0,quota=0,videoBytes=0;try{const e=await navigator.storage?.estimate?.();used=e?.usage||0;quota=e?.quota||0}catch{}for(const v of state.videos){try{if(v.storageMode==='opfs'){const b=await opfsGet(v.id);videoBytes+=b?.size||0}else if(v.storageMode==='indexeddb'){const b=await idbGet(v.id);videoBytes+=b?.size||0}else if(v.storageMode==='handle'){const h=await idbGetHandle(v.id);videoBytes+=(await h?.getFile())?.size||0}else if(v.src){const b=await (await fetch(v.src)).blob();videoBytes+=b.size||0}}catch{}}el.innerHTML=`<b>保存容量</b><span>ブラウザ使用 ${formatBytes(used)} / ${formatBytes(quota)}</span><span>動画 ${formatBytes(videoBytes)}</span><span>サムネイル ${formatBytes(thumbCacheBytes())}</span>`}
function applyUiPrefs(){document.documentElement.dataset.buttonSize=state.settings.buttonSize||'medium';document.documentElement.style.setProperty('--frame-repeat-ms',(state.settings.frameHoldMs||160)+'ms')}
function haptic(){if(state.settings.haptics)try{navigator.vibrate?.(8)}catch{}}
function setImmersive(on){state.immersive=!!on;const shell=$('.player-page');shell?.classList.toggle('immersive',state.immersive);const b=$('#immersive-toggle');if(b)b.textContent=state.immersive?'UI表示':'没入'}
function enhanceBoundUI(){applyUiPrefs();$$('button').forEach(b=>{if(!b.dataset.hapticBound){b.dataset.hapticBound='1';b.addEventListener('pointerdown',haptic,{passive:true})}});if(state.screen==='player'){const ov=$('.video-overlay'),stage=$('.video-stage');if(ov&&!$('#immersive-toggle')){const b=document.createElement('button');b.id='immersive-toggle';b.className='immersive-toggle';b.textContent=state.immersive?'UI表示':'没入';b.onclick=e=>{e.stopPropagation();setImmersive(!state.immersive);if(state.immersive)document.documentElement.requestFullscreen?.().catch(()=>{})};ov.appendChild(b)}setImmersive(state.immersive);if(stage){stage.addEventListener('click',e=>{if(state.immersive){e.stopImmediatePropagation();setImmersive(false)}},true);if(state.settings.landscapeAutoHide&&matchMedia('(orientation: landscape)').matches){let timer;const wake=()=>{setImmersive(false);clearTimeout(timer);timer=setTimeout(()=>setImmersive(true),2600)};stage.addEventListener('pointermove',wake,{passive:true});stage.addEventListener('touchstart',wake,{passive:true});wake()}}}}
function settings(){const fs=state.settings.favoriteSpeeds||[.25,.5,1];return `<div class="app-shell">${topbar('設定')}<main class="content settings-page"><section class="settings-group"><h3>再生</h3><div class="settings-list"><label class="setting-row"><span>戻る秒数</span><select id="set-back">${[1,3,5,10,30].map(x=>`<option ${state.settings.skipBack===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting-row"><span>進む秒数</span><select id="set-forward">${[1,3,5,10,30].map(x=>`<option ${state.settings.skipForward===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting-row"><span>再開時の自動巻き戻し</span><select id="set-rewind">${[0,1,2,3,5].map(x=>`<option value="${x}" ${state.settings.autoRewind===x?'selected':''}>${x}秒</option>`).join('')}</select></label><label class="setting-row"><span>低速時の音声</span><select id="set-low-audio"><option value="pitch" ${state.settings.lowSpeedAudio==='pitch'?'selected':''}>音程を保つ</option><option value="normal" ${state.settings.lowSpeedAudio==='normal'?'selected':''}>速度に合わせる</option><option value="mute" ${state.settings.lowSpeedAudio==='mute'?'selected':''}>ミュート</option></select></label><label class="setting-row"><span>よく使う速度 3件</span><span class="favorite-speed-inputs">${fs.map((x,i)=>`<select data-fav-speed-setting="${i}">${[.05,.1,.25,.5,.75,1,1.25,1.5,2].map(v=>`<option value="${v}" ${x===v?'selected':''}>${v}x</option>`).join('')}</select>`).join('')}</span></label><label class="setting-row"><span>コマ送り長押し間隔</span><select id="set-frame-hold">${[80,120,160,240,320].map(x=>`<option value="${x}" ${state.settings.frameHoldMs===x?'selected':''}>${x} ms</option>`).join('')}</select></label></div></section><section class="settings-group"><h3>メモ・タグ</h3><div class="settings-list"><label class="setting-row"><span>メモ作成時に一時停止</span><input id="set-note-pause" type="checkbox" ${state.settings.notePause?'checked':''}></label><label class="setting-row"><span>スクリーンショットを初期ON</span><input id="set-note-shot" type="checkbox" ${state.settings.noteAutoSnapshot?'checked':''}></label><label class="setting-row"><span>自動区間の既定 前 / 後</span><span><input class="small-number" id="set-auto-before" type="number" value="${state.settings.autoBefore||5}"> / <input class="small-number" id="set-auto-after" type="number" value="${state.settings.autoAfter||3}"> 秒</span></label></div><h4>メモ種別</h4>${noteKindSettingsHtml()}</section><section class="settings-group"><h3>表示</h3><div class="settings-list"><label class="setting-row"><span>外観</span><select id="set-theme"><option value="light" ${state.settings.theme==='light'?'selected':''}>ライト</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>ダーク</option></select></label><label class="setting-row"><span>動画表示</span><select id="set-fit"><option value="fit" ${state.settings.fitMode==='fit'?'selected':''}>全体を表示</option><option value="fill" ${state.settings.fitMode==='fill'?'selected':''}>画面いっぱい</option></select></label><label class="setting-row"><span>ボタンサイズ</span><select id="set-button-size"><option value="small" ${state.settings.buttonSize==='small'?'selected':''}>小</option><option value="medium" ${state.settings.buttonSize==='medium'?'selected':''}>標準</option><option value="large" ${state.settings.buttonSize==='large'?'selected':''}>大</option></select></label><label class="setting-row"><span>振動フィードバック</span><input id="set-haptics" type="checkbox" ${state.settings.haptics?'checked':''}></label><label class="setting-row"><span>タイムラインサムネイル密度</span><select id="set-thumb">${[6,8,10,12,16].map(x=>`<option ${state.settings.thumbDensity===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting-row"><span>横画面の右パネル幅</span><input id="set-panel" type="range" min="22" max="35" value="${state.settings.panelWidth||27}"></label><label class="setting-row"><span>横画面でUIを自動的に隠す</span><input id="set-landscape-hide" type="checkbox" ${state.settings.landscapeAutoHide?'checked':''}></label></div></section><section class="settings-group"><h3>書き出し</h3><div class="settings-list"><label class="setting-row"><span>静止画に描画を含める</span><input id="set-img-draw" type="checkbox" ${state.settings.exportImageDrawings?'checked':''}></label><label class="setting-row"><span>静止画に時刻を表示</span><input id="set-img-time" type="checkbox" ${state.settings.exportImageTime?'checked':''}></label><label class="setting-row"><span>クリップ速度</span><select id="set-clip-speed">${[.25,.5,.75,1].map(x=>`<option value="${x}" ${state.settings.clipSpeed===x?'selected':''}>${x}x</option>`).join('')}</select></label><label class="setting-row"><span>クリップに描画を焼き付ける</span><input id="set-clip-draw" type="checkbox" ${state.settings.clipDrawings?'checked':''}></label><label class="setting-row"><span>クリップ音声</span><input id="set-clip-audio" type="checkbox" ${state.settings.clipAudio?'checked':''}></label><label class="setting-row"><span>スロー音声</span><select id="set-clip-low-audio"><option value="pitch" ${state.settings.clipSlowAudio==='pitch'?'selected':''}>音程を保つ</option><option value="normal" ${state.settings.clipSlowAudio==='normal'?'selected':''}>速度に合わせる</option></select></label></div></section><section class="settings-group"><h3>保存</h3><div id="storage-estimate" class="storage-estimate"><b>保存容量</b><span>計算中…</span></div><div class="settings-list"><label class="setting-row"><span>サムネイルキャッシュ上限</span><select id="set-cache-limit">${[10,25,50,100].map(x=>`<option value="${x}" ${state.settings.thumbCacheLimitMB===x?'selected':''}>${x} MB</option>`).join('')}</select></label></div><div class="export-grid"><button class="btn" id="backup-export">分析データをバックアップ</button><button class="btn" id="backup-export-videos">動画込みバックアップ</button><button class="btn" id="backup-import">バックアップを復元</button><button class="btn" id="csv-export">シーン/タグ/集計CSV</button><button class="btn" id="cache-clear">サムネイルキャッシュ削除</button><button class="btn" id="storage-refresh">容量を再計算</button></div><input id="restore-file" type="file" accept="application/json,.psbundle" hidden></section><section class="settings-group"><h3>仕様・制限</h3><div class="notice-card"><b>Web版のフレーム制限</b><p>コマ送りはFPSに基づく近似です。VFRを含む実フレームPTS単位の移動のみ、ネイティブ版Media3/AVFoundationへ置き換える必要があります。</p></div><button class="btn danger-lite" id="reset-data">デモデータを初期化</button></section></main>${nav()}<div id="toast" class="toast"></div></div>`}
function bindSettings(){const upd=(k,val)=>{state.settings[k]=val;persist('settings')};$('#set-back').onchange=e=>upd('skipBack',+e.target.value);$('#set-forward').onchange=e=>upd('skipForward',+e.target.value);$('#set-rewind').onchange=e=>upd('autoRewind',+e.target.value);$('#set-low-audio').onchange=e=>upd('lowSpeedAudio',e.target.value);$$('[data-fav-speed-setting]').forEach(x=>x.onchange=e=>{state.settings.favoriteSpeeds[+x.dataset.favSpeedSetting]=+e.target.value;persist('settings')});$('#set-frame-hold').onchange=e=>upd('frameHoldMs',+e.target.value);$('#set-note-pause').onchange=e=>upd('notePause',e.target.checked);$('#set-note-shot').onchange=e=>upd('noteAutoSnapshot',e.target.checked);$('#set-auto-before').onchange=e=>upd('autoBefore',+e.target.value||0);$('#set-auto-after').onchange=e=>upd('autoAfter',+e.target.value||0);$('#set-theme').onchange=e=>{upd('theme',e.target.value);applyTheme()};$('#set-fit').onchange=e=>{upd('fitMode',e.target.value);state.videos.forEach(v=>v.fitMode=e.target.value);persist('videos')};$('#set-button-size').onchange=e=>{upd('buttonSize',e.target.value);applyUiPrefs()};$('#set-haptics').onchange=e=>upd('haptics',e.target.checked);$('#set-thumb').onchange=e=>upd('thumbDensity',+e.target.value);$('#set-panel').oninput=e=>{upd('panelWidth',+e.target.value);document.documentElement.style.setProperty('--panel-pct',e.target.value+'%')};$('#set-landscape-hide').onchange=e=>upd('landscapeAutoHide',e.target.checked);$('#set-img-draw').onchange=e=>upd('exportImageDrawings',e.target.checked);$('#set-img-time').onchange=e=>upd('exportImageTime',e.target.checked);$('#set-clip-speed').onchange=e=>upd('clipSpeed',+e.target.value);$('#set-clip-draw').onchange=e=>upd('clipDrawings',e.target.checked);$('#set-clip-audio').onchange=e=>upd('clipAudio',e.target.checked);$('#set-clip-low-audio').onchange=e=>upd('clipSlowAudio',e.target.value);$('#set-cache-limit').onchange=e=>{upd('thumbCacheLimitMB',+e.target.value);enforceThumbCacheLimit();refreshStorageEstimate()};$('#note-kind-add').onclick=()=>{state.settings.noteKinds.push({name:'新しい種別',color:COLORS[state.settings.noteKinds.length%COLORS.length]});persist('settings');render()};$$('[data-note-kind-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.noteKindUp,j=Math.max(0,i-1);[state.settings.noteKinds[i],state.settings.noteKinds[j]]=[state.settings.noteKinds[j],state.settings.noteKinds[i]];persist('settings');render()});$$('[data-note-kind-down]').forEach(b=>b.onclick=()=>{const i=+b.dataset.noteKindDown,j=Math.min(state.settings.noteKinds.length-1,i+1);[state.settings.noteKinds[i],state.settings.noteKinds[j]]=[state.settings.noteKinds[j],state.settings.noteKinds[i]];persist('settings');render()});$$('[data-note-kind-delete]').forEach(b=>b.onclick=()=>{state.settings.noteKinds.splice(+b.dataset.noteKindDelete,1);persist('settings');render()});$$('[data-note-kind-name]').forEach(x=>x.onchange=e=>{state.settings.noteKinds[+x.dataset.noteKindName].name=e.target.value.trim()||'種別';persist('settings')});$$('[data-note-kind-color]').forEach(x=>x.onchange=e=>{state.settings.noteKinds[+x.dataset.noteKindColor].color=e.target.value;persist('settings')});$('#backup-export').onclick=()=>exportBackup(false);$('#backup-export-videos').onclick=()=>exportBackup(true);$('#backup-import').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=importBackup;$('#csv-export').onclick=exportCsv;$('#cache-clear').onclick=()=>{state.videos.forEach(v=>delete v.thumbnails);persist('videos');toast('サムネイルキャッシュを削除しました');refreshStorageEstimate()};$('#storage-refresh').onclick=refreshStorageEstimate;$('#reset-data').onclick=()=>{DBKEYS.forEach(k=>localStorage.removeItem('ps2_'+k));location.reload()};refreshStorageEstimate()}
function exportCsv(){const rows=[['type','video','title','start','end','tag','time','count']];state.scenes.forEach(s=>rows.push(['scene',video(s.videoId)?.title,s.title,s.start,s.end,tagNames(s.tagIds),'','']));state.tagEvents.forEach(t=>rows.push(['tag',video(t.videoId)?.title,'',t.start??'',t.end??'',state.tagDefs.find(d=>d.id===t.tagId)?.name,t.time,'']));state.tagDefs.forEach(td=>{const count=state.scenes.filter(s=>(s.tagIds||[]).includes(td.id)).length;rows.push(['summary_tag','','','','',td.name,'',count])});state.videos.forEach(v=>{const count=state.tagEvents.filter(t=>t.videoId===v.id).length;rows.push(['summary_video',v.title,'','','','','',count])});const csv='\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\n');dl(new Blob([csv],{type:'text/csv;charset=utf-8'}),'playstudy-scenes-tags-summary.csv')}
function researchCardHtml(c){if(c.type==='scene'){const s=scene(c.refId),v=video(s?.videoId);return `<article class="scene-card draggable" draggable="true" data-research-card="${c.id}"><div class="thumb" style="${thumbStyle(v,s?.start||0)}"><span class="duration">${fmt(s?.start||0)}</span></div><h5>${esc(s?.title||'削除済み')}</h5><div class="meta">${fmt(s?.start||0)}–${fmt(s?.end||0)}${s?.favorite?' ★':''}</div><div class="mini-actions"><button data-open-video="${v?.id||''}" data-start="${s?.start||0}" data-scene-id="${s?.id||''}">再生</button><button data-remove-card="${c.id}">×</button></div></article>`}if(c.type==='comparison'){const cp=state.comparisons.find(x=>x.id===c.refId);return `<article class="scene-card compare-card draggable" draggable="true" data-research-card="${c.id}"><div class="compare-mini">⇆</div><h5>${esc(cp?.title||'比較')}</h5><div class="meta">保存比較</div><div class="mini-actions"><button data-open-comparison="${cp?.id||''}">開く</button><button data-remove-card="${c.id}">×</button></div></article>`}if(c.type==='image')return `<article class="scene-card draggable" draggable="true" data-research-card="${c.id}"><img class="research-image" src="${c.imageData||''}" alt="研究画像"><h5>${esc(c.text||'画像')}</h5><button data-remove-card="${c.id}">×</button></article>`;if(c.type==='link')return `<article class="scene-card draggable" draggable="true" data-research-card="${c.id}"><div class="compare-mini">↗</div><h5>${esc(c.text||c.url||'参考リンク')}</h5><a class="research-link" href="${esc(c.url||'#')}" target="_blank" rel="noopener">開く</a><button data-remove-card="${c.id}">×</button></article>`;return `<article class="scene-card draggable" draggable="true" data-research-card="${c.id}"><h5>${esc(c.text||'テキスト')}</h5><button data-remove-card="${c.id}">×</button></article>`}
function research(){const t=theme(state.activeTheme)||state.themes[0];if(!t)return researchEmpty();const cards=state.researchCards.filter(c=>c.themeId===t.id),stats=researchStats(t),unsorted=cards.filter(c=>c.lane==='未整理');return `<div class="app-shell research-page">${topbar('研究テーマ',false,'<button class="header-action" id="theme-switch">テーマ切替</button>')}<main class="content"><div class="theme-tabs">${state.themes.map(x=>`<button class="chip ${x.id===t.id?'active':''}" data-theme-pick="${x.id}">${esc(x.title)}</button>`).join('')}<button class="chip dashed" id="theme-new">＋</button></div><section class="theme-summary"><div class="theme-title-row"><div><div class="subtle">研究テーマ</div><h2>${esc(t.title)}</h2></div><button class="mini-outline" id="theme-edit">編集</button></div><div class="status-row"><span class="chip active">${esc(t.status)}</span><span class="chip">カード ${cards.length}</span><span class="chip">未整理 ${unsorted.length}</span><span class="chip">再確認 ${esc((t.revisitDate||'').slice(5).replace('-','/'))}</span>${(t.relatedTagIds||[]).map(id=>{const td=state.tagDefs.find(x=>x.id===id);return td?`<span class="chip">${esc(td.name)}</span>`:''}).join('')}</div><div class="question-card"><b>調べたいこと</b><p>${esc(t.question||'')}</p></div></section>${unsorted.length?`<section class="section unsorted-section"><div class="section-head"><h3>未整理</h3><span class="subtle">分類前のカード</span></div><div class="unsorted-row" data-drop-lane="未整理">${unsorted.sort((a,b)=>(a.order||0)-(b.order||0)).map(researchCardHtml).join('')}</div></section>`:''}<section class="section"><div class="section-head"><h3>研究ボード</h3><button class="link-btn" id="lane-manage">レーン管理</button></div><div class="board research-board">${t.lanes.filter(x=>x!=='未整理').map(l=>laneHtml(t,l)).join('')}</div></section><section class="research-bottom-grid"><div class="theme-summary"><b>仮説</b><p>${esc(t.hypothesis||'未入力')}</p><hr class="soft"><b>現時点の結論</b><p>${esc(t.conclusion||'まだ結論なし')}</p><hr class="soft"><b>次に試すこと</b><p>${esc(t.nextAction||'未入力')}</p></div><div class="theme-summary"><b>集計</b><div class="stat-grid"><div><strong>${stats.sceneCount}</strong><span>シーン</span></div><div><strong>${stats.success}</strong><span>成功</span></div><div><strong>${stats.miss}</strong><span>ミス</span></div><div><strong>${stats.videoCount}</strong><span>元動画</span></div></div><div class="tag-stat-list">${stats.tags.map(x=>`<span><i style="background:${x.color}"></i>${esc(x.name)} ${x.count}</span>`).join('')}</div><hr class="soft"><b>日付別</b><div class="mini-stat-list">${stats.dates.map(([d,c])=>`<span>${esc(d)} <b>${c}</b></span>`).join('')||'<span>なし</span>'}</div><b>タグ組合せ</b><div class="mini-stat-list">${stats.combos.map(x=>`<span>${esc(x.name)} <b>${x.count}</b></span>`).join('')||'<span>なし</span>'}</div><b>動画時間帯</b><div class="mini-stat-list"><span>前半1/3 <b>${stats.thirds[0]}</b></span><span>中盤1/3 <b>${stats.thirds[1]}</b></span><span>後半1/3 <b>${stats.thirds[2]}</b></span></div></div></section></main><button class="fab" id="research-add">+</button>${nav()}${themeDialog()}${laneDialog()}${researchAddDialog()}<div id="toast" class="toast"></div></div>`}
function openSavedComparison(id){const c=state.comparisons.find(x=>x.id===id);if(!c)return;state.compareLeftId=c.leftId;state.compareRightId=c.rightId;state.compareLeftSource=c.leftSource||makeCompareSourceValue(c.leftId,c.leftSceneId);state.compareRightSource=c.rightSource||makeCompareSourceValue(c.rightId,c.rightSceneId);state.compareMode=c.mode;state.compareDraft={...c};route('compare')}
function bindResearch(){$('#research-add').onclick=()=>$('#research-add-dialog').showModal();$('#theme-edit').onclick=()=>{state.editThemeId=state.activeTheme;render();setTimeout(()=>$('#theme-dialog').showModal(),0)};$('#theme-switch').onclick=()=>{const cur=state.themes.findIndex(t=>t.id===state.activeTheme);state.activeTheme=state.themes[(cur+1)%state.themes.length]?.id||state.activeTheme;render()};$('#theme-new')?.addEventListener('click',()=>{state.editThemeId=null;render();setTimeout(()=>$('#theme-dialog').showModal(),0)});$$('[data-theme-pick]').forEach(b=>b.onclick=()=>{state.activeTheme=b.dataset.themePick;render()});$('#lane-manage').onclick=()=>$('#lane-dialog').showModal();bindThemeDialog();bindLaneDialog();bindResearchAdd();bindResearchDrag();$$('[data-remove-card]').forEach(b=>b.onclick=()=>{state.researchCards=state.researchCards.filter(c=>c.id!==b.dataset.removeCard);persist('researchCards');render()});$$('[data-open-comparison]').forEach(b=>b.onclick=()=>openSavedComparison(b.dataset.openComparison))}
function playlistDialog(){const pl=state.playlists.find(x=>x.id===state.editPlaylistId);return `<dialog id="playlist-dialog"><div class="dialog-head"><h3>${pl?'プレイリスト編集':'プレイリスト作成'}</h3><button class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="field"><label>タイトル</label><input id="pl-title" value="${esc(pl?.title||'')}"></div><div class="field"><label>説明</label><input id="pl-desc" value="${esc(pl?.description||'')}"></div>${pl?`<div class="playlist-edit-list">${pl.items.map((it,i)=>{const s=scene(it.sceneId);return `<div class="playlist-edit-row draggable" draggable="true" data-pl-row="${i}"><b>${i+1}. ${esc(s?.title||'削除済み')}</b><label>回数 <input type="number" min="1" max="20" value="${it.loopCount||1}" data-pl-loop="${i}"></label><button data-pl-up="${i}">↑</button><button data-pl-down="${i}">↓</button><button data-pl-remove="${i}">×</button></div>`}).join('')}</div>`:''}<label class="check-row"><input id="pl-autoplay" type="checkbox" ${pl?.autoplayNext!==false?'checked':''}> 次のシーンを自動再生</label><label class="check-row"><input id="pl-pause-between" type="checkbox" ${pl?.pauseBetween?'checked':''}> シーン間で一時停止</label><div class="field"><label>シーン間の停止時間（秒）</label><input id="pl-pause-seconds" type="number" min="0" max="30" step="0.5" value="${pl?.pauseSeconds??1.5}"></div>${pl?'<button class="btn danger-lite full" id="pl-delete">削除</button>':''}</div><div class="dialog-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" id="pl-save">保存</button></div></dialog>`}
function bindPlaylistDialog(){const d=$('#playlist-dialog');if(!d)return;const pl=state.playlists.find(x=>x.id===state.editPlaylistId);$('#pl-save')?.addEventListener('click',()=>{if(pl){pl.title=$('#pl-title').value.trim()||pl.title;pl.description=$('#pl-desc').value.trim();pl.autoplayNext=$('#pl-autoplay').checked;pl.pauseBetween=$('#pl-pause-between').checked;pl.pauseSeconds=clamp(+$('#pl-pause-seconds').value||0,0,30);$$('[data-pl-loop]').forEach(x=>pl.items[+x.dataset.plLoop].loopCount=clamp(+x.value||1,1,20))}else state.playlists.push({id:uid('pl'),title:$('#pl-title').value.trim()||'無題プレイリスト',description:$('#pl-desc').value.trim(),items:[],autoplayNext:$('#pl-autoplay').checked,pauseBetween:$('#pl-pause-between').checked,pauseSeconds:clamp(+$('#pl-pause-seconds').value||0,0,30)});persist('playlists');d.close();render()});$$('[data-pl-up]').forEach(b=>b.onclick=()=>movePlaylistItem(pl,+b.dataset.plUp,-1));$$('[data-pl-down]').forEach(b=>b.onclick=()=>movePlaylistItem(pl,+b.dataset.plDown,1));$$('[data-pl-remove]').forEach(b=>b.onclick=()=>{pl.items.splice(+b.dataset.plRemove,1);persist('playlists');render();setTimeout(()=>{$('#playlist-dialog').showModal();bindPlaylistDialog()},0)});let from=null;$$('[data-pl-row]').forEach(row=>{row.ondragstart=()=>from=+row.dataset.plRow;row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const to=+row.dataset.plRow;if(pl&&from!=null&&to!==from){const [item]=pl.items.splice(from,1);pl.items.splice(to,0,item);persist('playlists');render();setTimeout(()=>{$('#playlist-dialog').showModal();bindPlaylistDialog()},0)}}});$('#pl-delete')?.addEventListener('click',()=>{state.playlists=state.playlists.filter(x=>x.id!==pl.id);persist('playlists');d.close();render()})}
