generateThumbnails=async function(vid,force=false){
 if(!vid.duration||!Number.isFinite(vid.duration))return;
 const frames=$$('[data-thumb]');if(!frames.length)return;
 const current=activeV();
 if(!force&&Array.isArray(current.thumbnails)&&current.thumbnails.length===frames.length){frames.forEach((frame,index)=>{if(current.thumbnails[index])frame.style.backgroundImage=`url(${current.thumbnails[index]})`;frame.dataset.done='1'});if(!current.poster&&current.thumbnails[0]){current.poster=current.thumbnails[0];persist('videos')}return}
 const restoreTime=vid.currentTime,wasPaused=vid.paused;vid.pause();
 const canvas=document.createElement('canvas'),context=canvas.getContext('2d'),count=frames.length,output=[];
 for(let index=0;index<count;index++){
  const time=index===0?0:Math.min(vid.duration-.03,(index+.5)/count*vid.duration);await seekAsync(vid,time);canvas.width=320;canvas.height=180;
  try{context.drawImage(vid,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.58);output.push(data);if(frames[index]){frames[index].style.backgroundImage=`url(${data})`;frames[index].dataset.done='1'}}catch{output.push(current.poster||'')}
 }
 await seekAsync(vid,restoreTime);current.thumbnails=output;if(output[0])current.poster=output[0];persist('videos');enforceThumbCacheLimit();if(!wasPaused)vid.play();
};
