/* ===== focused video zoom + compact linked research ===== */
function bindFocusVideoGestures(){
 const stage=$('#focus-stage'),vid=$('#main-video'),current=activeV(),signal=focusPlayerController?.signal;if(!stage||!vid||!current||!signal)return;
 current.zoom=clamp(+current.zoom||1,1,8);current.panX=+current.panX||0;current.panY=+current.panY||0;applyVideoTransform(vid,current);
 let badge=$('#focus-zoom-level');if(!badge){badge=document.createElement('div');badge.id='focus-zoom-level';badge.className='focus-zoom-level';stage.appendChild(badge)}
 const listen=(element,type,handler,options={})=>element.addEventListener(type,handler,{...options,signal}),pointers=new Map();let pinch=null,pan=null,moved=false,blockClickUntil=0,badgeTimer=0,primaryId=null;
 const point=event=>({x:event.clientX,y:event.clientY});
 const midpoint=values=>({x:(values[0].x+values[1].x)/2,y:(values[0].y+values[1].y)/2});
 const limitPan=()=>{if(current.zoom<=1.001){current.zoom=1;current.panX=0;current.panY=0;return}const rect=stage.getBoundingClientRect(),maxX=rect.width*(current.zoom-1)/2,maxY=rect.height*(current.zoom-1)/2;current.panX=clamp(current.panX,-maxX,maxX);current.panY=clamp(current.panY,-maxY,maxY)};
 const showZoom=()=>{clearTimeout(badgeTimer);badge.textContent=`${current.zoom.toFixed(current.zoom<2?1:0)}×`;badge.classList.add('is-visible');badgeTimer=setTimeout(()=>badge.classList.remove('is-visible'),700)};
 const apply=()=>{limitPan();applyVideoTransform(vid,current);stage.classList.toggle('is-zoomed',current.zoom>1.001);showZoom()};
 const cancelLongPress=()=>{if(primaryId==null||typeof PointerEvent!=='function')return;try{window.dispatchEvent(new PointerEvent('pointercancel',{pointerId:primaryId}))}catch{}};
 listen(stage,'pointerdown',event=>{if(event.target.closest('button,input,textarea,label,.focus-comment-sheet,.focus-seek-hit'))return;pointers.set(event.pointerId,point(event));if(pointers.size===1){primaryId=event.pointerId;pan={x:event.clientX,y:event.clientY,px:current.panX,py:current.panY};moved=false;return}if(pointers.size===2){const values=[...pointers.values()],mid=midpoint(values),rect=stage.getBoundingClientRect(),zoom=current.zoom||1;cancelLongPress();pinch={distance:Math.max(1,Math.hypot(values[0].x-values[1].x,values[0].y-values[1].y)),zoom,contentX:(mid.x-rect.left-rect.width/2-current.panX)/zoom,contentY:(mid.y-rect.top-rect.height/2-current.panY)/zoom};pan=null;moved=true;blockClickUntil=performance.now()+700;event.preventDefault();event.stopImmediatePropagation()}},{capture:true});
 listen(stage,'pointermove',event=>{if(!pointers.has(event.pointerId))return;pointers.set(event.pointerId,point(event));if(pointers.size===2&&pinch){const values=[...pointers.values()],mid=midpoint(values),rect=stage.getBoundingClientRect(),distance=Math.hypot(values[0].x-values[1].x,values[0].y-values[1].y),zoom=clamp(pinch.zoom*distance/pinch.distance,1,8);current.zoom=zoom;current.panX=mid.x-rect.left-rect.width/2-pinch.contentX*zoom;current.panY=mid.y-rect.top-rect.height/2-pinch.contentY*zoom;moved=true;blockClickUntil=performance.now()+700;apply();event.preventDefault();event.stopImmediatePropagation();return}if(pointers.size===1&&pan&&current.zoom>1){const dx=event.clientX-pan.x,dy=event.clientY-pan.y;if(!moved&&Math.hypot(dx,dy)>5){moved=true;cancelLongPress()}if(moved){current.panX=pan.px+dx;current.panY=pan.py+dy;blockClickUntil=performance.now()+500;apply();event.preventDefault();event.stopImmediatePropagation()}}},{capture:true});
 const finish=event=>{pointers.delete(event.pointerId);if(pinch&&pointers.size<2){pinch=null;blockClickUntil=performance.now()+650;persist('videos')}if(pointers.size===1&&current.zoom>1){const remaining=[...pointers.values()][0];pan={x:remaining.x,y:remaining.y,px:current.panX,py:current.panY}}else if(!pointers.size){pan=null;primaryId=null;if(moved)persist('videos')}};
 listen(stage,'pointerup',finish,{capture:true});listen(stage,'pointercancel',finish,{capture:true});listen(stage,'click',event=>{if(performance.now()<blockClickUntil){event.preventDefault();event.stopImmediatePropagation()}},{capture:true});
 stage.classList.toggle('is-zoomed',current.zoom>1.001);
}

state.editResearchCardId=null;
state.themes.forEach(item=>{if(!Array.isArray(item.relatedTagIds))item.relatedTagIds=[]});
const researchCardById=id=>state.researchCards.find(card=>card.id===id);
const researchNote=id=>state.notes.find(note=>note.id===id);
function researchRefOptions(type,selected=''){
 let items=[];
 if(type==='scene')items=state.scenes.map(item=>({id:item.id,label:`${item.title} — ${video(item.videoId)?.title||'動画なし'}`}));
 if(type==='video')items=state.videos.map(item=>({id:item.id,label:item.title}));
 if(type==='note')items=state.notes.map(item=>({id:item.id,label:`${fmt(item.time||0,true)} ${item.title||'無題メモ'} — ${video(item.videoId)?.title||'動画なし'}`}));
 if(type==='comparison')items=state.comparisons.map(item=>({id:item.id,label:item.title||'保存した比較'}));
 return items.map(item=>`<option value="${item.id}" ${item.id===selected?'selected':''}>${esc(item.label)}</option>`).join('');
}
function researchTypeName(type){return ({scene:'シーン',video:'動画',note:'メモ',comparison:'比較',text:'テキスト',image:'画像',link:'リンク'})[type]||'項目'}
researchCardHtml=function(card){
 const edit=`<button data-edit-research-card="${card.id}" aria-label="この研究カードを編集">編集</button>`;
 if(card.type==='scene'){const item=scene(card.refId),source=video(item?.videoId);return `<article class="scene-card draggable" draggable="true" data-research-card="${card.id}"><div class="thumb" style="${thumbStyle(source,item?.start||0)}"><span class="duration">${fmt(item?.start||0)}</span></div><h5>${esc(item?.title||'削除済み')}</h5><div class="meta">シーン・${esc(source?.title||'動画なし')}</div><div class="mini-actions"><button data-research-open-video="${source?.id||''}" data-start="${item?.start||0}">再生</button>${edit}</div></article>`}
 if(card.type==='video'){const source=video(card.refId);return `<article class="scene-card draggable" draggable="true" data-research-card="${card.id}"><div class="thumb" style="${thumbStyle(source)}"></div><h5>${esc(source?.title||'削除済み')}</h5><div class="meta">動画</div><div class="mini-actions"><button data-research-open-video="${source?.id||''}" data-start="${source?.last||0}">再生</button>${edit}</div></article>`}
 if(card.type==='note'){const note=researchNote(card.refId),source=video(note?.videoId);return `<article class="scene-card draggable research-note-card" draggable="true" data-research-card="${card.id}"><span class="research-card-kind">メモ ${fmt(note?.time||0,true)}</span><h5>${esc(note?.title||'削除済み')}</h5>${note?.body?`<p>${esc(note.body)}</p>`:''}<div class="mini-actions"><button data-research-open-video="${source?.id||''}" data-start="${note?.time||0}">場面へ</button>${edit}</div></article>`}
 if(card.type==='comparison'){const item=state.comparisons.find(value=>value.id===card.refId);return `<article class="scene-card compare-card draggable" draggable="true" data-research-card="${card.id}"><div class="compare-mini">⇆</div><h5>${esc(item?.title||'削除済み')}</h5><div class="mini-actions"><button data-open-comparison="${item?.id||''}">開く</button>${edit}</div></article>`}
 if(card.type==='image')return `<article class="scene-card draggable" draggable="true" data-research-card="${card.id}"><img class="research-image" src="${card.imageData||''}" alt=""><h5>${esc(card.text||'画像')}</h5><div class="mini-actions">${edit}</div></article>`;
 if(card.type==='link')return `<article class="scene-card draggable" draggable="true" data-research-card="${card.id}"><span class="research-card-kind">リンク</span><h5>${esc(card.text||card.url||'参考リンク')}</h5><div class="mini-actions"><a class="research-link" href="${esc(card.url||'#')}" target="_blank" rel="noopener">開く</a>${edit}</div></article>`;
 return `<article class="scene-card draggable" draggable="true" data-research-card="${card.id}"><span class="research-card-kind">テキスト</span><h5>${esc(card.text||'テキスト')}</h5><div class="mini-actions">${edit}</div></article>`;
};
themeDialog=function(){const item=theme(state.editThemeId);return `<dialog id="theme-dialog"><div class="dialog-head"><h3>${item?'研究を編集':'研究を作成'}</h3><button class="icon-btn" data-close aria-label="閉じる">×</button></div><div class="dialog-body compact-theme-form"><div class="field"><label>テーマ名</label><input id="th-title" value="${esc(item?.title||'')}"></div><div class="field"><label>調べたいこと</label><textarea id="th-question" rows="2">${esc(item?.question||'')}</textarea></div><div class="research-form-grid"><div class="field"><label>仮説</label><textarea id="th-hypothesis" rows="2">${esc(item?.hypothesis||'')}</textarea></div><div class="field"><label>結論</label><textarea id="th-conclusion" rows="2">${esc(item?.conclusion||'')}</textarea></div><div class="field"><label>次に試すこと</label><textarea id="th-next" rows="2">${esc(item?.nextAction||'')}</textarea></div></div><div class="range-fields"><div class="field"><label>状態</label><select id="th-status">${['場面収集中','検証中','一旦結論','改善確認中','完了','保留'].map(value=>`<option ${item?.status===value?'selected':''}>${value}</option>`).join('')}</select></div><div class="field"><label>再確認日</label><input id="th-date" type="date" value="${esc(item?.revisitDate||'')}"></div></div><div class="field"><label>関連タグ</label><div class="tag-checks compact-link-checks">${state.tagDefs.map(tag=>`<label><input type="checkbox" data-theme-tag="${tag.id}" ${(item?.relatedTagIds||[]).includes(tag.id)?'checked':''}><i style="background:${tag.color}"></i>${esc(tag.name)}</label>`).join('')}</div></div>${item?'<button class="btn danger-lite full" id="theme-delete">この研究を削除</button>':''}</div><div class="dialog-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" id="theme-save">保存</button></div></dialog>`};
function researchAddDialog(){const card=researchCardById(state.editResearchCardId),type=card?.type||'scene',linked=['scene','video','note','comparison'].includes(type);return `<dialog id="research-add-dialog"><div class="dialog-head"><h3>${card?'カードを編集':'研究に追加'}</h3><button class="icon-btn" data-close aria-label="閉じる">×</button></div><div class="dialog-body"><div class="range-fields"><div class="field"><label>種類</label><select id="ra-type">${[['scene','シーン'],['video','動画'],['note','メモ'],['comparison','保存した比較'],['text','テキスト'],['image','画像'],['link','外部リンク']].map(([value,label])=>`<option value="${value}" ${type===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>置き場所</label><select id="ra-lane">${(theme(state.activeTheme)?.lanes||['未整理']).map(lane=>`<option ${card?.lane===lane?'selected':''}>${esc(lane)}</option>`).join('')}</select></div></div><div class="field" id="ra-ref-wrap" ${linked?'':'hidden'}><label id="ra-ref-label">${researchTypeName(type)}</label><select id="ra-ref">${researchRefOptions(type,card?.refId||'')}</select></div><div class="field" id="ra-text-wrap" ${['text','image','link'].includes(type)?'':'hidden'}><label>表示名</label><input id="ra-text" value="${esc(card?.text||'')}" placeholder="カード名"></div><div class="field" id="ra-image-wrap" ${type==='image'?'':'hidden'}><label>画像</label><input id="ra-image" type="file" accept="image/*"><span class="subtle">変更しない場合は選択不要</span></div><div class="field" id="ra-url-wrap" ${type==='link'?'':'hidden'}><label>URL</label><input id="ra-url" type="url" value="${esc(card?.url||'')}" placeholder="https://..."></div>${card?'<button class="btn danger-lite full" id="ra-delete">このカードを削除</button>':''}</div><div class="dialog-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" id="ra-save">${card?'保存':'追加'}</button></div></dialog>`}
research=function(){const item=theme(state.activeTheme)||state.themes[0];if(!item)return researchEmpty();const cards=state.researchCards.filter(card=>card.themeId===item.id),stats=researchStats(item),unsorted=cards.filter(card=>card.lane==='未整理'),linkedVideos=new Set(cards.map(card=>card.type==='video'?card.refId:card.type==='scene'?scene(card.refId)?.videoId:card.type==='note'?researchNote(card.refId)?.videoId:null).filter(Boolean));return `<div class="app-shell research-page">${topbar('研究')}<main class="content research-compact"><div class="theme-tabs">${state.themes.map(value=>`<button class="chip ${value.id===item.id?'active':''}" data-theme-pick="${value.id}">${esc(value.title)}</button>`).join('')}<button class="chip dashed" id="theme-new" aria-label="研究を追加">＋</button></div><section class="theme-summary research-compact-summary"><div class="theme-title-row"><div><h2>${esc(item.title)}</h2><p class="research-question">${esc(item.question||'調べたいことを編集から追加')}</p></div><button class="mini-outline" id="theme-edit">編集</button></div><div class="status-row"><span class="chip active">${esc(item.status)}</span><span class="chip">${cards.length}件</span><span class="chip">動画 ${linkedVideos.size}</span>${item.revisitDate?`<span class="chip">再確認 ${esc(item.revisitDate.slice(5).replace('-','/'))}</span>`:''}${(item.relatedTagIds||[]).map(id=>{const tag=state.tagDefs.find(value=>value.id===id);return tag?`<span class="chip">${esc(tag.name)}</span>`:''}).join('')}</div></section>${unsorted.length?`<section class="section unsorted-section compact-unsorted"><div class="section-head"><h3>未整理</h3></div><div class="unsorted-row" data-drop-lane="未整理">${unsorted.sort((a,b)=>(a.order||0)-(b.order||0)).map(researchCardHtml).join('')}</div></section>`:''}<section class="section compact-board-section"><div class="section-head"><h3>ボード</h3><div class="research-board-actions"><button class="link-btn" id="lane-manage">レーン</button><button class="btn compact primary" id="research-add">＋ 追加</button></div></div><div class="board research-board">${item.lanes.filter(lane=>lane!=='未整理').map(lane=>laneHtml(item,lane)).join('')}</div></section><details class="research-insights"><summary>仮説・結論・集計</summary><div class="research-insight-grid"><section><b>仮説</b><p>${esc(item.hypothesis||'未入力')}</p></section><section><b>結論</b><p>${esc(item.conclusion||'未入力')}</p></section><section><b>次に試すこと</b><p>${esc(item.nextAction||'未入力')}</p></section></div><div class="research-stat-row"><span><b>${stats.sceneCount}</b> シーン</span><span><b>${stats.videoCount}</b> 動画</span><span><b>${stats.success}</b> 成功</span><span><b>${stats.miss}</b> ミス</span>${stats.tags.map(tag=>`<span><i style="background:${tag.color}"></i>${esc(tag.name)} ${tag.count}</span>`).join('')}</div></details></main>${nav()}${themeDialog()}${laneDialog()}${researchAddDialog()}<div id="toast" class="toast"></div></div>`};
bindThemeDialog=function(){const dialog=$('#theme-dialog');if(!dialog)return;const item=theme(state.editThemeId);$('#theme-save')?.addEventListener('click',()=>{if(item){item.title=$('#th-title').value.trim()||item.title;item.question=$('#th-question').value.trim();item.hypothesis=$('#th-hypothesis').value.trim();item.conclusion=$('#th-conclusion').value.trim();item.nextAction=$('#th-next').value.trim();item.status=$('#th-status').value;item.revisitDate=$('#th-date').value;item.relatedTagIds=$$('[data-theme-tag]:checked').map(input=>input.dataset.themeTag)}else{const created={id:uid('rt'),title:$('#th-title').value.trim()||'無題研究',question:$('#th-question').value.trim(),hypothesis:$('#th-hypothesis').value.trim(),conclusion:$('#th-conclusion').value.trim(),nextAction:$('#th-next').value.trim(),status:$('#th-status').value,revisitDate:$('#th-date').value,relatedTagIds:$$('[data-theme-tag]:checked').map(input=>input.dataset.themeTag),lanes:['未整理','成功例','改善例','参考','反例']};state.themes.push(created);state.activeTheme=created.id}persist('themes');state.editThemeId=null;dialog.close();render()});$('#theme-delete')?.addEventListener('click',()=>{const id=item.id;state.themes=state.themes.filter(value=>value.id!==id);state.researchCards=state.researchCards.filter(card=>card.themeId!==id);state.notes.forEach(note=>{if(note.themeId===id)note.themeId=''});state.activeTheme=state.themes[0]?.id;persistMany('themes','researchCards','notes');dialog.close();state.editThemeId=null;render()})};
function removeResearchCard(id){const card=researchCardById(id);if(!card)return;if(card.type==='note'){const note=researchNote(card.refId);if(note?.themeId===card.themeId)note.themeId=''}state.researchCards=state.researchCards.filter(value=>value.id!==id);normalizeOrders(card.themeId,card.lane);persistMany('researchCards','notes')}
bindResearchAdd=function(){const dialog=$('#research-add-dialog');if(!dialog)return;let card=researchCardById(state.editResearchCardId);const updateFields=()=>{const type=$('#ra-type').value,linked=['scene','video','note','comparison'].includes(type);$('#ra-ref-wrap').hidden=!linked;$('#ra-text-wrap').hidden=!['text','image','link'].includes(type);$('#ra-image-wrap').hidden=type!=='image';$('#ra-url-wrap').hidden=type!=='link';if(linked){$('#ra-ref-label').textContent=researchTypeName(type);$('#ra-ref').innerHTML=researchRefOptions(type,card?.type===type?card.refId:'')}};$('#ra-type').onchange=updateFields;$('#ra-delete')?.addEventListener('click',()=>{removeResearchCard(card.id);state.editResearchCardId=null;dialog.close();render()});$('#ra-save').onclick=async()=>{const type=$('#ra-type').value,lane=$('#ra-lane').value,text=$('#ra-text').value.trim(),refId=$('#ra-ref').value,imageFile=$('#ra-image').files[0],linkUrl=$('#ra-url').value.trim();if(['scene','video','note','comparison'].includes(type)&&!refId)return toast(`${researchTypeName(type)}がありません`);if(type==='image'&&!imageFile&&!card?.imageData)return toast('画像を選択してください');if(type==='link'&&!linkUrl)return toast('URLを入力してください');const previous=card?{...card}:null;if(!card){card={id:uid('rc'),themeId:state.activeTheme,type,refId:'',lane,order:999,text:''};state.researchCards.push(card)}card.type=type;card.lane=lane;card.refId=['scene','video','note','comparison'].includes(type)?refId:'';card.text=text;if(type==='image'){if(imageFile)card.imageData=await blobToDataURL(imageFile)}else delete card.imageData;if(type==='link')card.url=linkUrl;else delete card.url;if(previous?.type==='note'&&previous.refId!==card.refId){const oldNote=researchNote(previous.refId);if(oldNote?.themeId===card.themeId)oldNote.themeId=''}if(type==='note'){const note=researchNote(card.refId);if(note)note.themeId=card.themeId}if(previous)normalizeOrders(previous.themeId,previous.lane);normalizeOrders(card.themeId,card.lane);persistMany('researchCards','notes');state.editResearchCardId=null;dialog.close();render()};updateFields()};
bindResearch=function(){$('#research-add')?.addEventListener('click',()=>{state.editResearchCardId=null;render();setTimeout(()=>$('#research-add-dialog')?.showModal(),0)});$('#theme-edit')?.addEventListener('click',()=>{state.editThemeId=state.activeTheme;render();setTimeout(()=>$('#theme-dialog')?.showModal(),0)});$('#theme-new')?.addEventListener('click',()=>{state.editThemeId=null;render();setTimeout(()=>$('#theme-dialog')?.showModal(),0)});$$('[data-theme-pick]').forEach(button=>button.onclick=()=>{state.activeTheme=button.dataset.themePick;render()});$('#lane-manage')?.addEventListener('click',()=>$('#lane-dialog')?.showModal());$$('[data-edit-research-card]').forEach(button=>button.onclick=()=>{state.editResearchCardId=button.dataset.editResearchCard;render();setTimeout(()=>$('#research-add-dialog')?.showModal(),0)});$$('[data-research-open-video]').forEach(button=>button.onclick=()=>{const source=video(button.dataset.researchOpenVideo);if(!source)return toast('動画が見つかりません');source.last=+button.dataset.start||0;persist('videos');route('player',source.id)});$$('[data-open-comparison]').forEach(button=>button.onclick=()=>openSavedComparison(button.dataset.openComparison));bindThemeDialog();bindLaneDialog();bindResearchAdd();bindResearchDrag()};

const focusBaseBind=bind;
bind=function(){
 if(state.screen==='player'){bindFocusPlayer();bindFocusVideoGestures();return}
 focusPlayerController?.abort();focusPlayerController=null;focusBaseBind();if(state.screen==='library'){$$('[data-open-video][role="button"]').forEach(card=>card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();card.click()}}));backfillFirstFramePosters()}
};

window.addEventListener('resize',()=>{document.documentElement.style.setProperty('--panel-pct',(state.settings.panelWidth||27)+'%')});
document.documentElement.style.setProperty('--panel-pct',(state.settings.panelWidth||27)+'%');
window.addEventListener('beforeunload',persistAll);
restoreSession();
if(standaloneMode())state.screen='library';
if(!activeV())state.screen='library';
if(state.simpleMode){state.activeTab='memo';state.panelCollapsed=false;if(!['library','player'].includes(state.screen))state.screen='library'}
preferLandscape();
ensurePersistentStorage();
applyTheme();
applyUiPrefs();
render();
